const THEMES = {
  /* accent = gold used for labels and ornaments on that face; edge = the
     gold hairline around information panels. Both optional for older code. */
  ivory: { name: "Ivory", bg: "linear-gradient(168deg,#FCF8EE,#F1E8D4)", ink: "#15130F", sub: "#6E6556", rule: "rgba(126,97,29,.24)", accent: "#8A6A1E", edge: "rgba(176,141,42,.75)", dark: false, swatch: "#F5EDDA" },
  onyx:  { name: "Onyx",  bg: "linear-gradient(168deg,#1A1A1D,#0C0C0E)", ink: "#F2F0EA", sub: "#B9B6AE", rule: "rgba(240,238,232,.22)", accent: "#D9BE68", edge: "rgba(201,162,39,.55)", dark: true,  swatch: "#141416" },
  burgundy: { name: "Burgundy", bg: "linear-gradient(168deg,#4E1220,#230710)", ink: "#F6EDE4", sub: "#D9BFB1", rule: "rgba(226,194,122,.26)", accent: "#E2C27A", edge: "rgba(226,194,122,.55)", dark: true, swatch: "#4E1220" },
  slate: { name: "Forest", bg: "linear-gradient(168deg,#173028,#0A1712)", ink: "#F1F4F0", sub: "#B7CDBF", rule: "rgba(201,162,39,.28)", accent: "#D9BE68", edge: "rgba(201,162,39,.5)", dark: true,  swatch: "#12241D" },
  paper: { name: "Paper", bg: "linear-gradient(168deg,#FAFAF8,#ECEBE6)", ink: "#1A1A1C", sub: "#5E5D58", rule: "rgba(26,26,28,.18)", accent: "#8A6A1E", edge: "rgba(176,141,42,.6)", dark: false, swatch: "#F2F1EC" },
  silver: { name: "Silver", bg: "radial-gradient(120% 55% at 18% 0%,rgba(255,255,255,.95),rgba(255,255,255,0) 62%), linear-gradient(160deg,#FFFFFF 0%,#D3D8DF 16%,#9AA2AE 36%,#F2F4F7 52%,#AAB2BD 72%,#E6E9EE 88%,#B7BEC8 100%)", ink: "#0E0F12", sub: "#262A30", rule: "rgba(18,19,22,.22)", accent: "#3C4048", edge: "rgba(110,116,126,.8)", dark: false, swatch: "linear-gradient(135deg,#F6F7F9,#A9AFB9)", locked: true },
  gold: { name: "Gold", bg: "radial-gradient(120% 55% at 18% 0%,rgba(255,248,214,.9),rgba(255,248,214,0) 62%), linear-gradient(160deg,#FBEDB4 0%,#E7C060 22%,#B98A2B 48%,#F3D98A 62%,#C99A38 82%,#EBCB71 100%)", ink: "#14110A", sub: "#3A2D0F", rule: "rgba(20,17,10,.3)", accent: "#14110A", edge: "rgba(20,17,10,.55)", dark: false, swatch: "linear-gradient(135deg,#F7E3A0,#B98A2B)", locked: true },
};

const TIERS = {
  base:     { name: "Base",     ring: ["#B9B6AF", "#6E6B66"], face: "#1A1A1C", ink: "#CFCBC3" },
  standard: { name: "Standard", ring: ["#C9A227", "#7E611D"], face: "#111113", ink: "#E6CC80" },
  bronze:   { name: "Bronze",   ring: ["#D89A5C", "#7A4A20"], face: "#1A0F08", ink: "#F0C08A" },
  silver:   { name: "Silver",   ring: ["#E6E8EC", "#8D9298"], face: "#141416", ink: "#EFF1F4" },
  gold:     { name: "Gold",     ring: ["#F0D68A", "#9A7717"], face: "#131108", ink: "#F7E4A6" },
};

/* XP ladder — each rung names the tier metal it unlocks, so the reward badge
   is always drawn from the same Coin/FFEmblem art used everywhere else in
   the card system, never a separate gamification graphic. Extensible: add a
   rung here and the XP bar, profile badge and level-up state all follow. */
/* XP ladder. Bronze and Silver are fixed thresholds; Gold is NOT a number —
   it's awarded to the current quarter's top performers, so it can never be
   invented as a fixed XP figure. xpProgress() treats Gold as "reached" only
   when the caller says so (goldEligible), never from the xp value alone. */
const XP_LEVELS = [
  { tier: "bronze", xp: 100, label: "Bronze", unlocks: "First level of profile customisation" },
  { tier: "silver", xp: 500, label: "Silver", unlocks: "Additional profile customisation" },
  { tier: "gold",   xp: null, label: "Gold",   unlocks: "Premium profile customisation", earnedBy: "quarter-top-performers" },
];
const XP_NUMERIC_LEVELS = XP_LEVELS.filter(l => typeof l.xp === "number");


function quarterAfter(year, q) { return q === 4 ? { year: year + 1, q: 1 } : { year, q: q + 1 }; }
function quarterLabel(p) { return `${p.year} Q${p.q}`; }
function quarterMonths(p) { return QUARTER_MONTHS[p.q - 1]; }

function generateQuarters(startYear, startQ, count) {
  const out = [];
  let cur = { year: startYear, q: startQ };
  for (let i = 0; i < count; i++) { out.push(cur); cur = quarterAfter(cur.year, cur.q); }
  return out;
}

/* The single source of truth for "what quarter is it": change these two
   numbers and the whole XP Beta timeline, labels and reset behaviour move
   with it — nothing else in the app hardcodes a quarter. */
const XP_BETA_START = { year: 2026, q: 4 };
const XP_CURRENT_PERIOD = { year: 2026, q: 4 };
const XP_TIMELINE = generateQuarters(XP_BETA_START.year, XP_BETA_START.q, 5);
const xpPeriodKey = (p) => `${p.year}Q${p.q}`;

function xpProgress(xp) {
  const cur = xp || 0;
  const next = XP_NUMERIC_LEVELS.find(l => cur < l.xp);
  const prevXp = (() => {
    const i = next ? XP_NUMERIC_LEVELS.indexOf(next) : XP_NUMERIC_LEVELS.length;
    return i > 0 ? XP_NUMERIC_LEVELS[i - 1].xp : 0;
  })();
  const reached = XP_NUMERIC_LEVELS.filter(l => cur >= l.xp);
  const currentTier = reached.length ? reached[reached.length - 1].tier : "standard";
  if (!next) return { xp: cur, next: null, pct: 100, currentTier, prevXp, nextXp: cur || 1 };
  const span = next.xp - prevXp;
  const pct = span > 0 ? Math.min(100, Math.max(0, ((cur - prevXp) / span) * 100)) : 0;
  return { xp: cur, next, pct, currentTier, prevXp, nextXp: next.xp };
}

/* flagFor now lives with LANGUAGE_MASTER (Phase 1): real flag images, 52 languages. */

const CARD_DOMAIN = "ffparty.uk";

const A_GROUND = [["#2A2118", "#0A0A0C"], ["#241C22", "#0A0A0C"], ["#1B2028", "#08080A"], ["#2A211A", "#0B0A08"]];
const A_SKIN = [["#EFCFA8", "#966E49"], ["#D9A876", "#7A522F"], ["#B07B4E", "#5E3B21"], ["#8A5A36", "#472A16"], ["#6B4227", "#331D10"]];
const A_GARMENT = [["#17171A", "#08080A"], ["#1E1A16", "#0B0A08"], ["#241318", "#0D0709"], ["#15191F", "#080A0D"]];
const A_HAIR = ["#171310", "#2A1B10", "#4A3117", "#100E0C", "#5A4632"];

function avatarFor(seed) {
  const key = String(seed || "FireFlair");
  let h = 2166136261;
  for (let i = 0; i < key.length; i++) { h ^= key.charCodeAt(i); h = Math.imul(h, 16777619) >>> 0; }
  const at = (arr, shift) => arr[(h >>> shift) % arr.length];
  const [g1, g2] = at(A_GROUND, 2);
  const [sk1, sk2] = at(A_SKIN, 7);
  const [gm1, gm2] = at(A_GARMENT, 12);
  const hair = at(A_HAIR, 17);
  const style = (h >>> 22) % 4;
  const tie = (h >>> 27) % 3 === 0;
  const flip = (h >>> 29) % 2 === 1;

  const crown = "M55 64 C55 37 105 37 105 64 C105 49 95 41 80 41 C65 41 55 49 55 64 Z";
  const hairShape = {
    0: `<path d='M57 60 C57 40 103 40 103 60 C103 50 94 44 80 44 C66 44 57 50 57 60 Z' fill='${hair}'/>`,
    1: `<path d='${crown}' fill='${hair}'/>`,
    2: `<path d='${crown}' fill='${hair}'/><path d='M55 58 C50 86 52 112 57 126 L68 120 C62 104 60 80 61 62 Z' fill='${hair}'/><path d='M105 58 C110 86 108 112 103 126 L92 120 C98 104 100 80 99 62 Z' fill='${hair}'/>`,
    3: `<path d='${crown}' fill='${hair}'/><circle cx='80' cy='30' r='11' fill='${hair}'/>`,
  }[style];

  const svg = `<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160' viewBox='0 0 160 160'>`
    + `<defs>`
    + `<radialGradient id='bg' cx='36%' cy='26%' r='86%'><stop offset='0' stop-color='${g1}'/><stop offset='1' stop-color='${g2}'/></radialGradient>`
    + `<linearGradient id='sk' x1='0' y1='0' x2='1' y2='1'><stop offset='0' stop-color='${sk1}'/><stop offset='1' stop-color='${sk2}'/></linearGradient>`
    + `<linearGradient id='gm' x1='0' y1='0' x2='0' y2='1'><stop offset='0' stop-color='${gm1}'/><stop offset='1' stop-color='${gm2}'/></linearGradient>`
    + `</defs>`
    + `<rect width='160' height='160' fill='url(#bg)'/>`
    + `<circle cx='126' cy='34' r='17' fill='#C9A227' fill-opacity='.10'/>`
    + `<circle cx='30' cy='52' r='11' fill='#C9A227' fill-opacity='.08'/>`
    + `<circle cx='142' cy='96' r='8' fill='#EAD79C' fill-opacity='.07'/>`
    + `<g transform='${flip ? "translate(160,0) scale(-1,1)" : "translate(0,0)"}'>`
    + `<path d='M12 160 C16 118 42 100 64 94 L80 104 L96 94 C118 100 144 118 148 160 Z' fill='url(#gm)'/>`
    + `<path d='M70 78 h20 v24 l-10 7 -10 -7 Z' fill='url(#sk)' fill-opacity='.9'/>`
    + `<path d='M64 94 L80 106 L96 94 L96 104 L80 118 L64 104 Z' fill='#EFEAE0' fill-opacity='.9'/>`
    + (tie ? `<path d='M80 110 l-11 -5 v10 z M80 110 l11 -5 v10 z' fill='#1A1A1D'/><circle cx='80' cy='110' r='3' fill='#1A1A1D'/>` : ``)
    + `<ellipse cx='80' cy='66' rx='23' ry='28' fill='url(#sk)'/>`
    + hairShape
    + `<path d='M101 48 C110 60 110 80 100 92' stroke='#EAD79C' stroke-opacity='.55' stroke-width='2.5' fill='none' stroke-linecap='round'/>`
    + `<path d='M104 106 C118 110 132 124 138 144' stroke='#C9A227' stroke-opacity='.35' stroke-width='2' fill='none' stroke-linecap='round'/>`
    + `</g></svg>`;
  return `data:image/svg+xml;utf8,${encodeURIComponent(svg)}`;
}

function Corners() {
  return (<>
    <span className="ff-corner tl" /><span className="ff-corner tr" />
    <span className="ff-corner bl" /><span className="ff-corner br" />
  </>);
}

/* The official FF logo, one image per metal. Gold (with the red ring) is the
   brand mark and the standard coin; silver and the antique-gold version stand for the
   Silver and Bronze tiers. Inlined so the page needs no other host. */
const FF_LOGO_GOLD = "data:image/webp;base64,…(34 KB)";
const FF_LOGO_SILVER = "data:image/webp;base64,…(34 KB)";
const FF_LOGO_BRONZE = "data:image/webp;base64,…(30 KB)";
const FF_EMBLEM_SRC = { standard: FF_LOGO_GOLD, gold: FF_LOGO_GOLD, silver: FF_LOGO_SILVER, bronze: FF_LOGO_BRONZE };

const METAL = {
  base:     { edge: ["#EDEBE7", "#A9A6A0", "#55534F", "#9A978F", "#E2DFD9"], hair: "rgba(150,147,140,.40)", ink: "#D8D4CC", face: ["#2A2A2C", "#0C0C0D"] },
  standard: { edge: ["#F6E7B0", "#C9A227", "#5F4712", "#B99424", "#EFDB9A"], hair: "rgba(201,162,39,.40)", ink: "#F0DC9A", face: ["#2B2B31", "#0B0B0D"] },
  bronze:   { edge: ["#F2C89A", "#C07A3C", "#5A3315", "#B0692F", "#EABF8C"], hair: "rgba(200,126,62,.42)", ink: "#F0C08A", face: ["#2A1A10", "#0D0705"] },
  silver:   { edge: ["#FFFFFF", "#D4D8DE", "#767C85", "#C6CBD2", "#F4F6F9"], hair: "rgba(214,219,226,.40)", ink: "#EFF1F4", face: ["#2C2E33", "#0A0A0C"] },
  gold:     { edge: ["#FFF3C4", "#E8C75E", "#7A5C12", "#D8B443", "#FBEDB6"], hair: "rgba(232,199,94,.48)", ink: "#F9E9B4", face: ["#2E2714", "#0C0A05"] },
};
const metalOf = (tier) => METAL[tier] || METAL.standard;
const metalEdge = (tier, angle = 150) => {
  const m = metalOf(tier);
  return `linear-gradient(${angle}deg, ${m.edge[0]}, ${m.edge[1]} 24%, ${m.edge[2]} 50%, ${m.edge[3]} 74%, ${m.edge[4]})`;
};

const F_FORM = "M0 0 H24.5 V7.4 H8.6 V20.6 H20.4 V28 H8.6 V48 H0 Z";

let __ffIdSeq = 0;
function useSimpleId() { const r = useRef(null); if (r.current == null) r.current = `ffid${__ffIdSeq++}`; return r.current; }

function FFEmblem({ size = 40, tier = "standard", flat = false, style }) {
  const m = metalOf(tier);
  const id = useSimpleId();
  /* v1.3.3: "base" — a colourless, stencilled coin: white face, grey cut-out FF. */
  if (tier === "base") return (
    <svg width={size} height={size} viewBox="0 0 100 100" aria-hidden="true" style={{ display: "block", flex: "none", ...style }}>
      <circle cx="50" cy="50" r="48" fill="#FBFAF7" stroke="#BDB9B1" strokeWidth="3" />
      <circle cx="50" cy="50" r="40" fill="none" stroke="#CFCBC3" strokeWidth="1.4" strokeDasharray="3 3" />
      <g transform="translate(33.66 29.84) skewX(-9) scale(0.84)" fill="none" stroke="#8E8A82" strokeWidth="2.6" strokeLinejoin="round">
        <path d={F_FORM} />
        <g transform="translate(22 0)"><path d={F_FORM} /></g>
      </g>
    </svg>
  );
  const logo = FF_EMBLEM_SRC && (FF_EMBLEM_SRC[tier] || FF_EMBLEM_SRC.standard);
  if (logo) {
    /* v1.2: "base" — the greyed-out coin before Bronze. */
    const grey = tier === "base" ? { filter: "grayscale(1) brightness(2.1) contrast(.5) drop-shadow(0 0 1px rgba(0,0,0,.45))", opacity: .9 } : null;
    return <img src={logo} width={size} height={size} alt="" aria-hidden="true" draggable={false}
      style={{ display: "block", flex: "none", objectFit: "contain", ...grey, ...style }} />;
  }
  return (
    <svg width={size} height={size} viewBox="0 0 100 100" aria-hidden="true" style={{ display: "block", flex: "none", ...style }}>
      <defs>
        <linearGradient id={`e${id}`} x1="0.12" y1="0" x2="0.88" y2="1">
          <stop offset="0%" stopColor={m.edge[0]} /><stop offset="24%" stopColor={m.edge[1]} />
          <stop offset="50%" stopColor={m.edge[2]} /><stop offset="74%" stopColor={m.edge[3]} />
          <stop offset="100%" stopColor={m.edge[4]} />
        </linearGradient>
        <radialGradient id={`f${id}`} cx="36%" cy="26%" r="82%">
          <stop offset="0%" stopColor={m.face[0]} /><stop offset="100%" stopColor={m.face[1]} />
        </radialGradient>
        <linearGradient id={`t${id}`} x1="0.1" y1="0" x2="0.9" y2="1">
          <stop offset="0%" stopColor={m.edge[0]} /><stop offset="42%" stopColor={m.edge[1]} />
          <stop offset="70%" stopColor={m.edge[3]} /><stop offset="100%" stopColor={m.edge[4]} />
        </linearGradient>
        <linearGradient id={`s${id}`} x1="0" y1="0" x2="0.6" y2="1">
          <stop offset="0%" stopColor="#FFFFFF" stopOpacity=".6" />
          <stop offset="100%" stopColor="#FFFFFF" stopOpacity="0" />
        </linearGradient>
      </defs>

      <circle cx="50" cy="50" r="49" fill={`url(#e${id})`} />
      <circle cx="50" cy="50" r="43.5" fill={`url(#f${id})`} />
      {!flat && <circle cx="50" cy="50" r="40.6" fill="none" stroke="#8C1526" strokeWidth="1.5" opacity=".8" />}
      <circle cx="50" cy="50" r="37.4" fill="none" stroke={m.edge[1]} strokeWidth=".7" opacity=".5" />

      <g transform="translate(33.66 29.84) skewX(-9) scale(0.84)">
        <path d={F_FORM} fill={`url(#t${id})`} />
        <g transform="translate(22 0)">
          <path d={F_FORM} fill="none" stroke={m.face[1]} strokeWidth="3.4" strokeLinejoin="round" />
          <path d={F_FORM} fill={`url(#t${id})`} />
        </g>
      </g>

      <path d="M16 32 A40 40 0 0 1 58 11" fill="none" stroke={`url(#s${id})`} strokeWidth="3" strokeLinecap="round" opacity=".55" />
    </svg>
  );
}

function Coin({ size = 40, tier = "standard", flat = false, style }) {
  return <FFEmblem size={size} tier={tier} flat={flat} style={style} />;
}

const WM_LIGHT = "linear-gradient(100deg,#FBF0CA,#E6CE84 26%,#B08D2A 52%,#EBD695 74%,#FCF2D2)";
const WM_DARK = "linear-gradient(100deg,#9A7A24,#6F5514 30%,#B08D2A 52%,#7E611D 76%,#A5832B)";
function Wordmark({ size = 15, tone = "#EAD79C" }) {
  const onLight = tone !== "#EAD79C";
  const s = {
    fontFamily: "var(--display)", fontSize: size, letterSpacing: ".22em", whiteSpace: "nowrap",
    backgroundImage: onLight ? WM_DARK : WM_LIGHT, display: "inline-block",
  };
  return (<span className="ff-metal" style={s}>FIREFLAIR</span>);
}

/* ==========================================================================
   CARD PRIMITIVES
   ========================================================================== */

function CardFrame({ tier = "standard", theme, ratio, selected, onClick, style, className = "", hair = true, corners = false, premium = false, as = "div", children }) {
  const t = theme || THEMES.onyx;
  const m = metalOf(tier);
  const Tag = as;
  return (
    <Tag className={`ff-deck ${premium ? "pc" : ""} ${t.dark ? "" : "lite"} ${selected ? "ff-sel" : ""} ${className}`}
      onClick={onClick}
      style={{
        backgroundImage: `${t.bg}, ${metalEdge(tier)}`,
        aspectRatio: ratio, cursor: onClick ? "pointer" : undefined,
        border: premium ? "3px solid transparent" : "1px solid transparent",
        "--deck-hair": premium ? (t.edge || m.hair) : m.hair, ...style,
      }}>
      <span className="fx sheen" />
      <span className="fx grain" />
      {premium && <span className="fx wm" />}
      {hair && <span className="fx hair" />}
      {corners && <Corners />}
      {children}
    </Tag>
  );
}

function Portrait({ src, name, size = 92, ring = "#C9A227", ink = "#EAD79C", tier }) {
  const initials = (name || "").split(" ").map(w => w[0]).slice(0, 2).join("").toUpperCase();
  const band = size * 0.032 + 1.4;
  return (
    <div style={{
      width: size, height: size, borderRadius: "50%", flex: "none", padding: band,
      background: tier ? metalEdge(tier, 145) : `linear-gradient(145deg, ${ring}, ${ring})`,
      boxShadow: `0 ${size * 0.06}px ${size * 0.18}px rgba(0,0,0,.45), inset 0 0 0 1px rgba(255,255,255,.22)`,
    }}>
      <div role={src ? "img" : undefined} aria-label={src ? `Photo of ${name || "profile"}` : undefined} style={{
        width: "100%", height: "100%", borderRadius: "50%", position: "relative", overflow: "hidden",
        border: "1px solid rgba(8,8,10,.9)",
        background: src ? `url("${src}") center/cover` : "radial-gradient(circle at 38% 30%,#26262B,#0A0A0C)",
        display: "flex", alignItems: "center", justifyContent: "center",
        boxShadow: "inset 0 2px 9px rgba(0,0,0,.6)",
      }}>
        {!src && <span style={{ fontFamily: "var(--display)", color: ink, fontSize: size * 0.3, letterSpacing: ".05em", opacity: .85 }}>{initials}</span>}
        <span style={{ position: "absolute", inset: 0, borderRadius: "50%", background: "radial-gradient(64% 46% at 30% 16%, rgba(255,255,255,.20), transparent 62%)" }} />
      </div>
    </div>
  );
}




/* PROFESSIONS — FF Team Profession & Question Reference v1.6.
   People choose professions, never categories. The system assigns each
   profession to one of seven display categories; the person's top (first)
   profession decides where they appear on Network. Five suggestions per
   category for quick picking; any profession can be typed in. */
const PROFESSION_CATEGORIES = [
  { key: "Bar",            suggested: ["Barback", "Bartender", "Cocktail Bartender", "Flair Bartender", "Mixologist"] },
  { key: "Front of House", suggested: ["Waiter", "Host", "Front of House", "Event Host", "Catering Assistant"] },
  { key: "Management",     suggested: ["Event Manager", "Event Planner", "Bar Manager", "Floor Manager", "Kitchen Manager"] },
  { key: "Entertainment",  suggested: ["DJ", "Saxophonist", "Violinist", "Singer", "Magician"] },
  { key: "Services",       suggested: ["Photographer", "Videographer", "Content Creator", "Influencer", "Event Stylist"] },
  { key: "Chefs",          suggested: ["Chef", "Private Chef", "Event Chef", "Sous Chef", "Caterer"] },
  { key: "Back of House",  suggested: ["Stock Manager", "Stock Controller", "Kitchen Porter", "Kitchen Assistant", "Logistics Assistant"] },
];
const CATEGORY_ORDER = [...PROFESSION_CATEGORIES.map(c => c.key), "Other"];
/* Assignment for professions outside the suggestion lists. Checked in this
   order, so "Bar Manager" is Management and "Kitchen Porter" Back of House. */
const PROFESSION_RULES = [
  ["Management", /\b(manager|planner|coordinator|director|supervisor)\b/],
  ["Back of House", /\b(stock|porter|kitchen assistant|logistics|cellar)\b/],
  ["Bar", /\b(bar|bartend\w*|mixolog\w*|barback|barista|sommelier)\b/],
  ["Chefs", /\b(chef|cook|caterer|pastry|baker)\b/],
  ["Front of House", /\b(waiter|waitress|host|hostess|front of house|server|catering assistant|usher|runner)\b/],
  ["Entertainment", /\b(dj|music\w*|singer|sax\w*|violin\w*|magician|mc|band|performer|dancer|entertainer)\b/],
  ["Services", /\b(photo\w*|video\w*|content|influencer|stylist|florist|make-?up|decor\w*)\b/],
];
/* Category for one profession; null when it can't be determined (FireFlair then
   asks the person to confirm). An explicit override always wins. */
function professionCategory(name, override) {
  if (override) return override;
  const n = String(name || "").trim().toLowerCase();
  if (!n) return null;
  const exact = PROFESSION_CATEGORIES.find(c => c.suggested.some(x => x.toLowerCase() === n));
  if (exact) return exact.key;
  const rule = PROFESSION_RULES.find(([, re]) => re.test(n));
  return rule ? rule[0] : null;
}
const personCategory = (p) => professionCategory(p.profession, p.categoryOverride) || "Other";

