/* --- FF XP · 2027: the FF coin pop-up ---------------------------------
   The only way into XP. Next steps, then your tier and level, then how FF XP
   works. Uses the prototype's own XP logic (XP_TASKS, XP_VALUES, XP_LEVELS,
   xpProgress, quarterly periods) unchanged. */
function XPPopup({ open, onClose }) {
  const { state, dispatch } = useStore();
  const people = useDirectory();
  if (!open) return null;
  const p = state.profile;
  const live = !!p.live;
  const cardReady = recsOf(p, "professions").some(r => !r.proposed);
  const net = myNetwork(state, people).list.length;
  const lv = verificationLevel(net);
  const go = (tab, focus) => {
    onClose();
    if (state.role !== "team") dispatch({ type: "ROLE", role: "team" });
    dispatch({ type: "TAB", tab, route: "home" });
    if (focus) dispatch({ type: "FOCUS", focus: { target: focus } }); else window.scrollTo(0, 0);
  };
  const steps = [
    { id: "build", label: "Build your profile", hint: "Your Profile Card, professions and experience", done: cardReady, onClick: () => go("profile", "card") },
    { id: "share", label: "Share your Profile Card", hint: "Publish and send it on WhatsApp", done: live, onClick: () => go("profile", live ? "card" : "share") },
    { id: "grow", label: "Grow your network", hint: `${net} connection${net === 1 ? "" : "s"} so far`, done: net >= VERIFICATION_LEVELS[1].connections, onClick: () => go("network") },
  ];
  return (
    <Sheet open onClose={onClose} title="FF XP · 2027">
      <div className="ff-xpsec">
        <h3 className="ff-h2" style={{ fontSize: 16, marginBottom: 10 }}>Next steps</h3>
        {steps.map(t => (
          <button key={t.id} type="button" className={`ff-task${t.done ? " done" : ""}`} onClick={t.onClick}>
            <span className="dot">{t.done && <Check size={13} strokeWidth={2.6} />}</span>
            <span style={{ flex: 1, minWidth: 0 }}>
              <span className="ff-serif" style={{ fontSize: 15.5, display: "block", color: "#1D1B18", lineHeight: 1.2 }}>{t.label}</span>
              <span className="ff-body ff-muted" style={{ fontSize: 11.5 }}>{t.hint}</span>
            </span>
            {t.done ? <Pill tone="ok">Done</Pill> : <ChevronRight size={16} color="var(--gold-dk)" style={{ flex: "none" }} />}
          </button>
        ))}
      </div>

      <div className="ff-xpsec">
        <h3 className="ff-h2" style={{ fontSize: 16, marginBottom: 10 }}>Verification levels</h3>
        <div className="ff-xptier">
          <Coin size={52} tier={lv.tier} />
          <div style={{ flex: 1, minWidth: 0 }}>
            <span className="ff-display" style={{ fontSize: 22, display: "block" }}>{lv.name}</span>
            <span className="ff-body ff-muted" style={{ fontSize: 12 }}>
              {net} network connection{net === 1 ? "" : "s"}{lv.next ? ` · ${lv.next.connections - net} more for ${lv.next.name}` : ""}
            </span>
          </div>
        </div>
        <div className="ff-xplevels">
          {VERIFICATION_LEVELS.map(l => {
            const reached = l.connections !== null && net >= l.connections;
            return (
              <div key={l.tier} className={`ff-xplevel${reached ? " on" : ""}${lv.tier === l.tier ? " now" : ""}`}>
                <Coin size={26} tier={l.tier} />
                <span style={{ flex: 1, minWidth: 0 }}>
                  <b>{l.name}</b>
                  <small>{l.note}</small>
                </span>
                {l.connections === null ? <Pill><Lock size={10} /> Locked</Pill> : reached ? <Pill tone="ok"><Check size={10} /> Reached</Pill> : null}
              </div>
            );
          })}
        </div>
      </div>

      <div className="ff-xpsec">
        <h3 className="ff-h2" style={{ fontSize: 16, marginBottom: 8, display: "flex", alignItems: "center", gap: 8 }}>FF XP <span className="ff-soonbadge sm">Coming 2027</span></h3>
        <p className="ff-body" style={{ margin: 0, fontSize: 13.5, lineHeight: 1.55 }}>
          XP is rewarded for building, sharing and growing your profile. The more connections you have, the more XP you're rewarded, and the more your verification level grows.
        </p>
      </div>

      <div className="ff-xpsec">
        <h3 className="ff-h2" style={{ fontSize: 16, marginBottom: 8 }}>FF Rewards</h3>
        <div className="ff-xprewards">
          <p>Your XP level earns verification, which helps you get bookings. We're also building rewards — from bar show trips and training tickets to pro kit and an FF Christmas party.</p>
          <Btn variant="primary wide" onClick={() => { onClose(); if (state.role !== "team") dispatch({ type: "ROLE", role: "team" }); dispatch({ type: "TAB", tab: "bookings", route: "home" }); setTimeout(() => { const el = document.getElementById("ff-rewards"); if (el) el.scrollIntoView({ behavior: "auto", block: "start" }); }, 450); }}>
            <Award size={14} /> {state.rewardsInterest ? "You're on the list — see rewards" : "Register interest"}
          </Btn>
        </div>
      </div>
    </Sheet>
  );
}

/* --- Bookings (Phase 1) ---------------------------------------------------
   What works now first in each part, futures as Coming Soon cards: booked
   shifts (Coming 2027), FF Party Service Cards (register interest),
   Availability (peak dates), Training and Dream jobs (register interest). */
function P1Bookings({ guest = false }) {
  const { state, dispatch } = useStore();
  const svcInterest = state.profile.serviceInterest || [];
  const goProfile = () => { dispatch({ type: "ROLE", role: "team" }); dispatch({ type: "TAB", tab: "profile", route: "home" }); window.scrollTo(0, 0); };
  const toggleService = (sv) => {
    if (guest) { goProfile(); dispatch({ type: "TOAST", toast: "Create your Profile Card first, then register for Service Cards" }); return; }
    const on = svcInterest.includes(sv.id);
    dispatch({ type: "PROFILE", patch: { serviceInterest: on ? svcInterest.filter(x => x !== sv.id) : [...svcInterest, sv.id] } });
    dispatch({ type: "TOAST", toast: on ? `Withdrawn from ${sv.title}` : `Registered for ${sv.title}. We'll review your profile.` });
  };
  const jump = (id) => scrollToSection(id);
  const onSubmit = (v) => {
    const t = v.toLowerCase();
    if (/\b(rewards?|perks|gifts?|xp)\b/.test(t)) return jump("ff-rewards");
    if (/\b(train|training|course|wset|masterclass|learn|qualif)/.test(t)) return jump("ff-training");
    if (/\b(festival|yacht|motorsport|abroad|international|cruise|ski|dream|job)/.test(t)) return jump("ff-jobs");
    if (/\b(christmas|halloween|new year|nye|available|availability|dates?|free)\b/.test(t)) return jump("ff-bk-avail");
    if (/\b(service|party|mixology|masterclass|bartending)\b/.test(t)) return jump("ff-bk-party");
    return jump("ff-bk-booked");
  };
  return (
    <div>
      <div className="ff-eyebrow">{guest ? "FireFlair" : "FF Team"}</div>
      <h1 className="ff-h1" style={{ marginTop: 4 }}>Bookings</h1>

      <FFAI title="Search your bookings" onSubmit={onSubmit}
        purpose="Get ready for bookings: tell FireFlair when you're free, which Service Cards you can perform, and the training and jobs you want."
        placeholder="Christmas, mixology, festivals…"
        actions={[
          { label: "Availability", onClick: () => jump("ff-bk-avail") },
          { label: "Service Cards", onClick: () => jump("ff-bk-party") },
          { label: "Training", onClick: () => jump("ff-training") },
          { label: "Dream jobs", onClick: () => jump("ff-jobs") },
          { label: "Rewards", onClick: () => jump("ff-rewards") },
        ]} />

      <section id="ff-bk-booked" className="ff-bkpart">
        <SectionHead icon={<Calendar size={15} color="var(--gold-dk)" strokeWidth={1.6} />} title="Your bookings" />
        <div className="ff-soonpanel">
          <div className="ff-wa" style={{ marginBottom: 12 }}>
            <span className="ff-wa-ico"><WhatsAppIcon size={22} /></span>
            <span className="ff-body" style={{ color: "#0B3D22", fontSize: 13.5 }}>
              <b>Requests come to you on WhatsApp.</b> When companies and clients ask if you're free, each request is sent to you directly on WhatsApp and shows here. You reply in either place.
            </span>
          </div>
          <p className="ff-soonpanel-lede">Your booked shifts will be shown here. Bookings open with FF Business and FF Party.</p>
          <div className="ff-soongrid">
            <SoonCard icon={WaGlyph} title="Requests from companies" note="Businesses ask if you're free, on WhatsApp. You reply there or here." when="Coming with FF Business" />
            <SoonCard icon={Calendar} title="Booked shifts" note="Confirmed shifts with the venue, times and directions, in one place." when="Coming with FF Business and FF Party" />
            <SoonCard icon={Wallet} title="Booking passes" note="Each confirmed booking as a pass in Apple Wallet or Google Wallet." when="Coming 2027" />
          </div>
        </div>
      </section>

      <div className="ff-bkgroup-h">
        <span className="ff-eyebrow">Available now</span>
        <h2 className="ff-h2">Get ready for bookings</h2>
      </div>

      <section id="ff-bk-party" className="ff-bkpart">
        <SectionHead icon={<Martini size={15} color="var(--gold-dk)" strokeWidth={1.6} />} title="FF Party Service Cards"
          action={<Pill tone="gold">{svcInterest.length ? `${svcInterest.length} registered` : "Register interest"}</Pill>} />
        <p className="ff-body" style={{ marginTop: -2, fontSize: 13.5 }}>
          Register for the Service Cards you can perform. We'll review your profile, and once FF Party launches, your profile will be advertised alongside those Service Cards.
        </p>
        <HScroll label="FF Party Service Cards" snap>
          {PARTY_SERVICES.map(sv => {
            const on = svcInterest.includes(sv.id);
            return (
              <div key={sv.id} style={{ width: CARD_W.poster }}>
                <ServicePoster svc={sv} />
                <div className="ff-svcreg">
                  {on ? (<>
                    <span className="ff-svcreg-on"><Check size={14} strokeWidth={2.6} /> Registered · we'll review your profile</span>
                    <button type="button" className="ff-linkbtn" onClick={() => toggleService(sv)}>Withdraw</button>
                  </>) : (
                    <Btn variant="primary wide" onClick={() => toggleService(sv)}><Star size={14} /> Register interest</Btn>
                  )}
                </div>
              </div>
            );
          })}
        </HScroll>
      </section>

      <section id="ff-bk-avail" className="ff-bkpart">
        <SectionHead icon={<Clock size={15} color="var(--gold-dk)" strokeWidth={1.6} />} title="Availability" />
        <p className="ff-body" style={{ marginTop: -2, fontSize: 13.5 }}>
          Answer once and it's saved. Businesses see your answer when they ask about a date, and you're first in line on the busiest dates of the year.
        </p>
        <AvailabilityCards />
        <div className="ff-bkgroup-h" style={{ margin: "18px 0 8px" }}><span className="ff-eyebrow">Busy dates</span></div>
        <PeakAvailability />
      </section>

      <TrainingSection />
      <JobsSection />
      <P1RewardsSection />
    </div>
  );
}





/* --- Networking (Phase 1) -------------------------------------------------- */
/* What FireFlair Core has to provide for networking. None of it exists in the
   backend yet (FireFlair-Backend dev has no network, invitation or review
   endpoints), so the prototype keeps everything in this viewer's own store
   and says so on screen. Function bodies are what Core replaces. */
const NETWORK_ADAPTER = {
  connected: false,
  note: "Prototype: invitations, connections and reviews are kept in this preview only. Nothing is sent.",
  /* Core: POST /network/invitations { toPhone | toTag, review? }  → WhatsApp link */
  /* Core: on sign-up from an invitation link, connect inviter ⇄ invitee automatically */
  /* Core: GET /network  — the signed-in user's connections, inviter first */
  /* Core: POST /reviews { aboutTag, workedBefore, workAgain, howTo, rating, text } → pending until accepted */
};

function InvitedByBanner({ person, onReview }) {
  const { dispatch } = useStore();
  if (!person) return null;
  const first = String(person.name || "").split(" ")[0];
  const view = () => { dispatch({ type: "VIEW", id: person.id }); window.scrollTo(0, 0); };
  return (
    <div className="ff-invitedby">
      <div style={{ display: "flex", gap: 12, alignItems: "center" }}>
        <button type="button" onClick={view} aria-label={`Open ${person.name}'s profile`} style={{ flex: "none" }}>
          <Portrait src={person.photo} name={person.name} size={56} tier={person.tier} />
        </button>
        <div style={{ minWidth: 0 }}>
          <span className="ff-invited"><Star size={11} fill="currentColor" /> Invited you</span>
          <div className="ff-display" style={{ fontSize: 15, marginTop: 6 }}>{person.name}</div>
          <div className="ff-serif" style={{ fontSize: 13, color: "var(--gold-dk)", fontStyle: "italic" }}>{person.profession}</div>
        </div>
      </div>
      <p className="ff-body" style={{ margin: "12px 0 6px" }}>{person.name} invited you to FireFlair, so {first} is in your network automatically. You don't need to search for {first} or connect again.</p>
      <p className="ff-body ff-muted" style={{ fontSize: 12.5, margin: "0 0 10px" }}>Worked with {first}? Leave a review.</p>
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
        <Btn variant="sm primary" onClick={onReview}><Award size={12} /> Review {first}</Btn>
        <Btn variant="sm" onClick={view}><Eye size={12} /> View profile</Btn>
      </div>
    </div>
  );
}

/* Invitations you've sent: people not on FireFlair yet (INVITE) and team
   invitations to people who are (TEAM_INVITE). The preview buttons show what
   happens when they act; in production that comes from Core. */
function SentInvitations() {
  const { state, dispatch } = useStore();
  const directory = useDirectory();
  const teams = (state.teamInvites || []).filter(i => i.status === "pending");
  const teamTags = new Set(teams.map(i => String(i.tag || "").toLowerCase()));
  /* Contacts invited from the contact list: not on FireFlair yet (they join),
     or on FireFlair but not in this demo directory (they accept). */
  const joins = (state.invitations || []).filter(c => !c.joined && !(c.tag && teamTags.has(String(c.tag).toLowerCase()))
    && !(state.connections || []).some(x => x.id === `inv_${c.id}` || (c.tag && x.tag === c.tag)));
  if (!joins.length && !teams.length) return null;
  const preview = (c) => {
    const id = `inv_${c.id}`;
    dispatch({ type: "INVITE_JOINED", person: staff({ id, name: c.name, tag: c.tag || (c.name.replace(/[^A-Za-z]/g, "").slice(0, 4) + "1").toUpperCase(), profession: c.note && !/worked|together/i.test(c.note) ? c.note : "Bartender", group: "Bartenders", tier: "standard", level: 1, years: 1, rating: null, reviews: 0, skills: [], interests: [], languages: ["English"], locations: [] }) });
    dispatch({ type: "TOAST", toast: c.onFF ? `${c.name.split(" ")[0]} accepted · now in your network` : `${c.name.split(" ")[0]} joined · added to your network automatically` });
  };
  return (
    <section style={{ marginTop: 22 }}>
      <SectionHead icon={<Send size={15} color="var(--gold-dk)" strokeWidth={1.6} />} title="Invitations you've sent" count={joins.length + teams.length} />
      <div className="ff-sentlist">
        {teams.map(i => {
          const p = directory.find(x => x.id === i.personId);
          const first = String(i.name || "").split(" ")[0];
          return (
            <div key={i.id} className="ff-sentrow">
              <Portrait src={p && p.photo} name={i.name} size={34} tier={p && p.tier} />
              <span style={{ flex: 1, minWidth: 0 }}><b>{i.name}</b><small>Team invitation · waiting for {first} to accept</small></span>
              <button type="button" className="ff-linkbtn" onClick={() => {
                dispatch({ type: "TEAM_INVITE_ACCEPT", id: i.id });
                if (i.workedBefore && (i.review || i.rating)) dispatch({ type: "REVIEW_ADD", review: { id: uid("rev"), aboutId: i.personId, byId: "me", shiftId: null, byName: state.profile.name || "You", rating: i.rating || 5, text: i.review || `${i.howTo} to work with.`, at: Date.now() } });
                dispatch({ type: "TOAST", toast: `${first} accepted · now in your network` });
              }}>Preview: {first} accepts</button>
            </div>
          );
        })}
        {joins.map(c => (
          <div key={c.id} className="ff-sentrow">
            <Portrait name={c.name} size={34} ring="#B9B1A2" />
            <span style={{ flex: 1, minWidth: 0 }}><b>{c.name}</b><small>{c.onFF ? `On FireFlair · waiting for ${c.name.split(" ")[0]} to accept` : "Invited on WhatsApp · not on FireFlair yet"}</small></span>
            <button type="button" className="ff-linkbtn" onClick={() => preview(c)}>Preview: {c.name.split(" ")[0]} {c.onFF ? "accepts" : "joins"}</button>
          </div>
        ))}
      </div>
      <p className="ff-body ff-muted" style={{ fontSize: 11.5, margin: "8px 0 0" }}>{NETWORK_ADAPTER.note} The preview links show what happens when they act.</p>
    </section>
  );
}

/* A small note under prototype-only actions, so a mock is never mistaken for
   a live connection. */
function ProtoNote({ children }) {
  return <p className="ff-protonote"><Lock size={10} /> {children || NETWORK_ADAPTER.note}</p>;
}

/* --- Phase 1 footer ------------------------------------------------------ */
function Phase1Footer() {
  return (
    <footer className="ff-p1foot">
      <Coin size={22} tier="gold" />
      <span><b>{PHASE1.name}</b> · v{PHASE1.version} · {PHASE1.status.toLowerCase()}. Anything marked Coming 2027 isn't live yet. Sign-up codes, saving and FireFlair run inside this preview; notes for developers are on GitHub.</span>
    </footer>
  );
}

/* --- Legacy Word (.doc) CVs ------------------------------------------------
   Neither the prototype nor the backend could read .doc (Word 97–2003)
   files before: the backend's documentReader takes PDF, .docx, text and
   images. This reads the text straight out of the file: the OLE compound
   file, then the WordDocument stream's piece table (FIB → CLX → PlcPcd).
   Encrypted files and Word 6/95 files are refused with a clear message. */
function cfbStreams(buf) {
  const v = new DataView(buf), u8 = new Uint8Array(buf);
  const sig = [0xD0, 0xCF, 0x11, 0xE0, 0xA1, 0xB1, 0x1A, 0xE1];
  if (u8.length < 512 || sig.some((b, i) => u8[i] !== b)) throw cvxError("unreadable", "This doesn't look like a Word (.doc) file. Upload a PDF or .docx instead.");
  const secSize = 1 << v.getUint16(0x1E, true), miniSize = 1 << v.getUint16(0x20, true);
  const dirStart = v.getInt32(0x30, true), miniCutoff = v.getUint32(0x38, true);
  const miniFatStart = v.getInt32(0x3C, true), difatStart = v.getInt32(0x44, true);
  const off = (s) => (s + 1) * secSize;
  const fatSecs = [];
  for (let i = 0; i < 109; i++) { const s = v.getInt32(0x4C + i * 4, true); if (s >= 0) fatSecs.push(s); }
  for (let d = difatStart, guard = 0; d >= 0 && guard < 4096; guard++) {
    const per = secSize / 4 - 1;
    for (let i = 0; i < per; i++) { const s = v.getInt32(off(d) + i * 4, true); if (s >= 0) fatSecs.push(s); }
    d = v.getInt32(off(d) + per * 4, true);
  }
  const fat = [];
  fatSecs.forEach(s => { for (let i = 0; i < secSize / 4; i++) fat.push(v.getInt32(off(s) + i * 4, true)); });
  const chain = (start, table) => { const out = []; for (let s = start, g = 0; s >= 0 && g < table.length + 1; g++) { out.push(s); s = table[s]; } return out; };
  const readChain = (start, size) => {
    const out = new Uint8Array(size); let pos = 0;
    for (const s of chain(start, fat)) { const n = Math.min(secSize, size - pos); if (n <= 0) break; out.set(u8.subarray(off(s), off(s) + n), pos); pos += n; }
    return out;
  };
  /* Directory */
  const dirBytes = (() => { const secs = chain(dirStart, fat); const out = new Uint8Array(secs.length * secSize); secs.forEach((s, i) => out.set(u8.subarray(off(s), off(s) + secSize), i * secSize)); return out; })();
  const dv = new DataView(dirBytes.buffer);
  const entries = [];
  for (let p = 0; p + 128 <= dirBytes.length; p += 128) {
    const nlen = dv.getUint16(p + 0x40, true);
    const name = String.fromCharCode(...new Uint16Array(dirBytes.buffer.slice(p, p + Math.max(0, nlen - 2))));
    entries.push({ name, type: dirBytes[p + 0x42], start: dv.getInt32(p + 0x74, true), size: dv.getUint32(p + 0x78, true) });
  }
  const root = entries[0];
  const miniFat = miniFatStart >= 0 ? (() => { const b = readChain(miniFatStart, chain(miniFatStart, fat).length * secSize); const d2 = new DataView(b.buffer); const t = []; for (let i = 0; i < b.length / 4; i++) t.push(d2.getInt32(i * 4, true)); return t; })() : [];
  const miniStream = root && root.start >= 0 ? readChain(root.start, root.size) : new Uint8Array(0);
  const get = (name) => {
    const e = entries.find(x => x.type === 2 && x.name === name);
    if (!e) return null;
    if (e.size < miniCutoff) {
      const out = new Uint8Array(e.size); let pos = 0;
      for (const s of chain(e.start, miniFat)) { const n = Math.min(miniSize, e.size - pos); if (n <= 0) break; out.set(miniStream.subarray(s * miniSize, s * miniSize + n), pos); pos += n; }
      return out;
    }
    return readChain(e.start, e.size);
  };
  return { get };
}
const CP1252_HI = { 0x80: 0x20AC, 0x82: 0x201A, 0x83: 0x0192, 0x84: 0x201E, 0x85: 0x2026, 0x86: 0x2020, 0x87: 0x2021, 0x88: 0x02C6, 0x89: 0x2030, 0x8A: 0x0160, 0x8B: 0x2039, 0x8C: 0x0152, 0x8E: 0x017D, 0x91: 0x2018, 0x92: 0x2019, 0x93: 0x201C, 0x94: 0x201D, 0x95: 0x2022, 0x96: 0x2013, 0x97: 0x2014, 0x98: 0x02DC, 0x99: 0x2122, 0x9A: 0x0161, 0x9B: 0x203A, 0x9C: 0x0153, 0x9E: 0x017E, 0x9F: 0x0178 };
function docText(buf) {
  const cfb = cfbStreams(buf);
  const wd = cfb.get("WordDocument");
  if (!wd) throw cvxError("unreadable", "This file has no Word document inside. Upload a PDF or .docx instead.");
  const w = new DataView(wd.buffer, wd.byteOffset, wd.byteLength);
  if (w.getUint16(0, true) !== 0xA5EC) throw cvxError("unreadable", "This Word file is too old to read here (Word 6/95). Save it as .docx or PDF and upload that.");
  const flags = w.getUint16(0x0A, true);
  if (flags & 0x0100) throw cvxError("unreadable", "This Word file is password-protected. Remove the password, or upload a PDF.");
  const table = cfb.get(flags & 0x0200 ? "1Table" : "0Table");
  if (!table) throw cvxError("unreadable", "This Word file couldn't be read. Save it as .docx or PDF and upload that.");
  const csw = w.getUint16(32, true);
  const cslwAt = 34 + csw * 2, cslw = w.getUint16(cslwAt, true);
  const fcAt = cslwAt + 2 + cslw * 4 + 2;
  const fcClx = w.getUint32(fcAt + 33 * 8, true), lcbClx = w.getUint32(fcAt + 33 * 8 + 4, true);
  const t = new DataView(table.buffer, table.byteOffset, table.byteLength);
  let p = fcClx;
  while (p < fcClx + lcbClx && table[p] === 0x01) p += 3 + t.getUint16(p + 1, true);   // skip Prc
  if (table[p] !== 0x02) throw cvxError("unreadable", "This Word file couldn't be read. Save it as .docx or PDF and upload that.");
  const lcb = t.getUint32(p + 1, true), plc = p + 5, n = (lcb - 4) / 12;
  let text = "";
  for (let i = 0; i < n; i++) {
    const cp0 = t.getUint32(plc + i * 4, true), cp1 = t.getUint32(plc + (i + 1) * 4, true);
    const fcRaw = t.getUint32(plc + (n + 1) * 4 + i * 8 + 2, true);
    const compressed = (fcRaw & 0x40000000) !== 0, fc = fcRaw & 0x3FFFFFFF, count = cp1 - cp0;
    if (compressed) {
      const start = fc / 2;
      for (let k = 0; k < count && start + k < wd.length; k++) { const b = wd[start + k]; text += String.fromCharCode(CP1252_HI[b] || b); }
    } else {
      for (let k = 0; k < count && fc + k * 2 + 1 < wd.length; k++) text += String.fromCharCode(w.getUint16(fc + k * 2, true));
    }
  }
  /* Table rows end with a second cell mark: make that a line break. */
  text = text.replace(/\x07\x07/g, "\x07\r");
  /* Fields: keep the result, drop the instruction. Then tidy control marks. */
  let out = "", hide = [];
  for (const ch of text) {
    const c = ch.charCodeAt(0);
    if (c === 0x13) { hide.push(true); continue; }
    if (c === 0x14) { if (hide.length) hide[hide.length - 1] = false; continue; }
    if (c === 0x15) { hide.pop(); continue; }
    if (hide.some(Boolean)) continue;
    out += c === 0x0D || c === 0x0B || c === 0x0C ? "\n" : c === 0x07 ? "\t" : c === 0x09 || c === 0x0A || c >= 0x20 ? ch : "";
  }
  return out.replace(/\t+\n/g, "\n").replace(/[ \t]+$/gm, "").replace(/\n{3,}/g, "\n\n").trim();
}
async function readDoc(file, onStage) {
  onStage && onStage("Opening your Word file…");
  const text = docText(await file.arrayBuffer());
  if (text.replace(/\s/g, "").length < 20) throw cvxError("unreadable", "No text was found in this Word file. Save it as PDF and upload that.");
  const doc = newDoc("doc", file);
  doc.pageTexts = [text];
  doc.pageCount = doc.pagesRead = 1;
  return doc;
}

