  if (/[\w.+-]+@[\w-]+\.[\w.]+/.test(blob)) out.push("an e-mail address appears in metadata");
  if (/\+?\d[\d\s().-]{8,}\d/.test(blob)) out.push("a phone-number-like string appears in metadata");
