    seo = view({ ...pub, name: "A".repeat(80) }); checked++;
    if (seo.title.length > FF_SEO.title.max) fail("[long name] title not clipped: " + seo.title.length);
    seo = ffSeoFor({ ...base, role: null, tab: "network", viewing: "t2" }, [{ id: "t2", name: "  " }]); checked++;
