              <select className="u" value={i.unit} aria-label="Unit" onChange={(e) => pickUnit(i, e.target.value)}>{UNITS17.map(u => <option key={u} value={u}>{u}</option>)}{n === 20 && <option value="bottle">bottle (70 cl)</option>}</select>
              {sr ? <select className="nm sp" value={other ? "other" : (i.name || "")} aria-label="Spirit" onChange={(e) => { const v = e.target.value; if (v === "other") set({ spirit: "other", ings: c.ings.map(x => x.id === i.id ? { ...x, name: "", other: true } : x) }); else set({ spirit: v, spiritOther: "", ings: c.ings.map(x => x.id === i.id ? { ...x, name: v, other: false } : x) }); }}>
                  <option value="">Spirit</option>{SPIRITS17.map(x => <option key={x} value={x}>{x}</option>)}<option value="other">Other…</option></select>
                : <input className="nm" value={i.name} placeholder="Ingredient" maxLength={40} aria-label="Ingredient" onChange={(e) => setIng(i.id, { name: e.target.value })} />}
              <select className="by" value={i.buy || guessBuy17(i.name)} aria-label="Shopping list group" onChange={(e) => setIng(i.id, { buy: e.target.value })}>{BUY_ORDER17.map(k => <option key={k} value={k}>{BUY17[k].short}</option>)}</select>
