  const interests = String(c.interests || "").split(/[·,\n]/).map(x => x.trim()).filter(Boolean);
  const pics = (c.media || []).map(m => ({ id: m.id, src: m.src || m.dataUrl, name: m.name || "" })).filter(m => m.src);
