function ProfileGate17({ kind }) {
  const { state, dispatch } = useStore();
  const live = kind === "team" && !!state.profile.live;
  const done = live || !!(state.devDone || {})[kind];
  /* Editing lives in the store for every site, so the bar and the page always agree. */
  const editing = done && state.ed17 === kind;
  const snap = useRef(null);
  const [justShared, setJustShared] = useState(false);
  const was = useRef(live);
  /* "Your Profile Card is shared" shows once, at the bottom, when sign-up is completed here. */
  useEffect(() => {
    if (live && !was.current && !["dev", "demo"].includes(state.auth.method)) setJustShared(true);
    was.current = live;
  }, [live]);
  const edit = () => {
    snap.current = state.company || {};
    /* The demo business and host open in the editor with the details shown on their profile. */
    if (kind !== "team" && !String((state.company || {}).name || "").trim()) {
      const demo = kind === "party" ? { ...DEMO_HOST17, tier: undefined, photo: (window.FF_IMG || {}).face_you || "" } : (() => { const { id, mine, tier, ...rest } = companyList(state).find(x => !x.mine) || {}; return rest; })();
      dispatch({ type: "COMPANY_SAVE", company: { ...demo, joinedAt: Date.now() } });
      snap.current = { ...snap.current, ...demo };
    }
    dispatch({ type: "V11_SET", patch: { ed17: kind } });
    if (kind === "team") dispatch({ type: "PE_START" });
    window.scrollTo(0, 0);
  };
  const close = () => { flushPv17(); dispatch({ type: "V11_SET", patch: { ed17: null } }); dispatch({ type: "PE_DONE" }); window.scrollTo(0, 0); };
  const cancel = () => { if (kind !== "team" && snap.current) dispatch({ type: "COMPANY_SAVE", company: snap.current }); close(); };
  const save = () => {
    if (kind === "team") window.dispatchEvent(new Event("ff-save"));
    dispatch({ type: "TOAST", toast: "Saved" });
    close();
  };
  /* One Save: it also publishes. Edit while viewing your own profile; Cancel + Save while editing; Save while building. */
  useLiveAction17({
    status: done ? (editing ? "Editing your profile" : "Your profile is live") : "Building your profile",
    actions: done
      ? (editing
        ? [{ key: "cancel", label: "Cancel", icon: <S17I.X size={14} />, onClick: cancel }, { key: "save", label: "Save", icon: <S17I.Check size={14} />, onClick: save, primary: true }]
        : [{ key: "edit", label: "Edit", icon: <S17I.Pencil size={14} />, onClick: edit, primary: true }])
      : [{ key: "save", label: "Save", icon: <S17I.Check size={14} />, onClick: () => window.dispatchEvent(new Event("ff-save")), primary: true }],
  }, [done, editing, kind]);
  return (
    <div className={`ff-pg17${done ? " done" : ""}`}>
      {done && !editing ? <><DoneProfile17 kind={kind} />{justShared && kind === "team" && <div className="ff-pg17-shared"><PublishedPanel /></div>}</>
        : done ? (kind === "team" ? <ProfilePage /> : <StaffEdit17 kind={kind} />)
        : kind === "team" ? <ProfilePage /> : <StaffProfile />}
    </div>
  );
}

