/* The same pick buttons as the glassware: one or several. */
function PkgPick17({ edit, multi, value = [], opts, onChange, cols = 3 }) {
  if (!edit) return <b>{opts.filter(([k]) => value.includes(k)).map(([, l]) => l).join(", ") || (multi ? "All sizes" : "Not set")}</b>;
  return (
    <div className={`ff-c17-glass pk c${cols}`} role={multi ? "group" : "radiogroup"}>
      {opts.map(([k, l]) => { const on = value.includes(k); return (
        <button key={k} type="button" role={multi ? "checkbox" : "radio"} aria-checked={on} className={on ? "on" : ""}
          onClick={() => onChange(multi ? (on ? value.filter(x => x !== k) : [...value, k]) : [k])}><small>{l}</small></button>); })}
    </div>
  );
}
/* What each FireFlair package is chosen from: the people who offer it (or the bar companies). */
const BNOUN17 = { svc_bartending: ["bartender", "bartenders"], svc_mixology: ["mixologist", "mixologists"], svc_masterclass: ["mixologist", "mixologists"], svc_flair: ["flair bartender", "flair bartenders"], svc_full: ["bar company", "bar companies"], svc_staffing: ["event staff member", "event staff"] };
function PartyBrowse17() {
  const { state, dispatch } = useStore();
  const all = useDirectory();
  const [q, setQ] = useState(() => state.netQuery || "");
  useEffect(() => { if (state.netQuery) dispatch({ type: "NET_QUERY", q: "" }); }, []);
  const br = state.br17 || {};
  const cat = br.cat || "", band = br.band || "";
  const setBr = (p) => dispatch({ type: "V11_SET", patch: { br17: { ...br, ...p } } });
  const qual = br.q || "";
  const rank = (x) => !qual ? 0 : x.tone === qual ? 0 : 1;
  const list = cat ? pkgsOf17(state).filter(x => x.cat === cat && (!band || x.bands.includes(band))).map((x, i) => ({ x, i })).sort((a, b) => rank(a.x) - rank(b.x) || a.i - b.i).map(o => o.x) : [];
  const [pop, setPop] = useState(null);
  const ffList = list.filter(x => x.ff), others = list.filter(x => !x.ff);
  const cos = companyList(state).filter(c => !c.mine);
  const countOf = (svc) => svc.by ? 0 : svc.id === "svc_full" ? cos.length : all.filter(p => signedUp11(p, svc.id)).length;
  const jump = useRef(false);
  useEffect(() => { if (jump.current && cat) { jump.current = false; const el = document.getElementById("ff-br17-pk"); if (el) el.scrollIntoView({ behavior: "smooth", block: "start" }); } }, [cat]);
  const book = (svc) => {
    const label = (PARTY_BANDS11.find(b => b.k === band) || {}).guests || "";
    let ev = state.events.find(e => e.id === state.activeEventId);
    let evId = ev && ev.id;
    if (!evId) {
      evId = uid("evt");
      dispatch({ type: "EVENT_ADD", event: { id: evId, ...eventData11({ ...eventDraft11(null), band, aud: "", guests: label }), band, audience: "", site: "party", phone: state.bookPhone || "", email: state.bookEmail || "", questionIds: [] } });
      dispatch({ type: "ACTIVE_EVENT", id: evId });
    } else if (band && !ev.band) dispatch({ type: "EVENT_PATCH", id: evId, patch: { band, guests: label } });
    if (qual) dispatch({ type: "EVENT_PATCH", id: evId, patch: { quality: qual } });
    const have = state.shifts.some(x => x.eventId === evId && x.svcId === svc.id);
    if (!have) dispatch({ type: "SHIFT_ADD", shift: { id: uid("shf"), eventId: evId, staffIds: [], staffId: "", skills: [], qty: 1, dress: "", notes: "", tcs: "company", rate: "", total: "", hoursM: "", pay: svc.price,
      role: svc.title, matchRole: SVC_ROLE[svc.id] || svc.title, svcId: svc.id, svcPrice: svc.price, svcTime: svc.time, svcLevel: svc.level, time: svcTimeFor(svc, (ev && ev.start) || ""), date: (ev && ev.date) || "", iso: (ev && ev.iso) || "", venue: (ev && ev.venue) || "" } });
    dispatch({ type: "V11_SET", patch: { bkView: { eventId: evId } } });
    dispatch({ type: "TOAST", toast: `${svc.title} added to your event` });
    dispatch({ type: "TAB", tab: "bookings" }); window.scrollTo(0, 0);
  };
  const row = (items, title) => items.length > 0 && (
    <section className="ff-br17-row"><h2 className="ff-about-h">{title}</h2>
      <HScroll label={title}>{items.map(svc => {
        const n = svc.ff ? countOf(svc) : 0, noun = (BNOUN17[svc.id] || ["person", "people"])[n === 1 ? 0 : 1];
        return <div className="ff-br17-co" key={svc.id}><PkgCard17 svc={svc} n={n} noun={noun} match={!!qual && svc.tone === qual} onOpen={() => setPop(svc)} /></div>; })}</HScroll>
    </section>);
  const feat = TOP_STAFF11.map(id => all.find(p => p.id === id)).filter(Boolean);
  return (
    <div className="ff-pn ff-br17">
      <div className="ff-eyebrow">FF Party</div>
      <h1 className="ff-h1" style={{ marginTop: 4, marginBottom: 10 }}>Let's plan your party</h1>
      <p className="ff-br17-intro">Browse ready-made packages, explore bar companies, or search for the individual people you would love at your event.</p>
      <h2 className="ff-about-h ff-br17-q">What are you looking for?</h2>
      <div className="ff-br17-cats" role="group" aria-label="What are you looking for?">
        {BCATS17.map(b => <button key={b.k} type="button" className={`${b.k === "bar" ? "bar " : ""}${cat === b.k ? "on" : ""}`} aria-pressed={cat === b.k} onClick={() => { jump.current = cat !== b.k; setBr({ cat: cat === b.k ? "" : b.k }); }}><b.Ic size={28} /><span>{b.label}</span></button>)}
      </div>
      <h2 className="ff-about-h ff-br17-q">How many guests?</h2>
      <div className="ff-br17-bands" role="group" aria-label="How many guests?">
        {PARTY_BANDS11.map(b => <button key={b.k} type="button" className={band === b.k ? "on" : ""} aria-pressed={band === b.k} onClick={() => setBr({ band: band === b.k ? "" : b.k })}>{b.label}</button>)}
      </div>
      <h2 className="ff-about-h ff-br17-q">Preferred quality</h2>
      <div className="ff-br17-qual" role="group" aria-label="Preferred quality">
        {QUALITY17.map(o => <button key={o.k} type="button" className={`${o.k}${qual === o.k ? " on" : ""}`} aria-pressed={qual === o.k} onClick={() => setBr({ q: qual === o.k ? "" : o.k })}><b>{o.label}</b><small>{o.sub}</small></button>)}
      </div>
      <section className="ff-pn-sec" id="ff-pn-companies"><SectionHead icon={<I11.Briefcase size={15} color="var(--gold-dk)" strokeWidth={1.6} />} title="Featured companies" count={cos.length} />
        <HScroll label="Featured companies">{cos.map(c => <div className="ff-br17-co" key={c.id}><CompanyListing11 co={c} /></div>)}</HScroll></section>
      {cat && <div id="ff-br17-pk">
        {list.length === 0 && <p className="ff-body ff-muted" style={{ margin: "18px 0 0" }}>No {BCATS17.find(b => b.k === cat).label.toLowerCase()} packages for that many guests yet.</p>}
        {row(ffList, "FireFlair packages")}
        {row(others, "From FireFlair professionals")}
      </div>}
      <section className="ff-pn-sec"><SectionHead icon={<I11.Star size={15} color="var(--gold-dk)" strokeWidth={1.6} />} title="Featured people" count={feat.length} />
        <HScroll label="Featured people">{feat.map(p => <PlayerTile key={p.id} person={p} onClick={() => { dispatch({ type: "VIEW", id: p.id }); window.scrollTo(0, 0); }} />)}</HScroll></section>
      {pop && <PkgSheet17 svc={pop} band={band} qual={qual} people={pop.by ? [] : all.filter(p => p.id !== "me" && signedUp11(p, pop.id))} onClose={() => setPop(null)} />}
      {state.netBrief && <BookingBrief brief={state.netBrief} />}
      <FFAI query={q} onQuery={setQ} title="Search for your team" context="FF Party"
        purpose="Find the right people for your event: search by name, profession, skill or area."
        placeholder="Name, profession, skill or area…" />
      {!state.netBrief && <GroupedPeople query={q} onPick={(p) => dispatch({ type: "VIEW", id: p.id })} scope="staff_" />}
    </div>
  );
}

/* The FF coin is the notification centre on every site. Next steps (and XP, later) sit under the notifications. */
function NotifySheet17({ open, onClose, onNext }) {
  const { state, dispatch } = useStore();
  if (!open) return null;
  const items = [];
  (state.events || []).forEach(ev => {
    const open_ = (state.shifts || []).filter(x => x.eventId === ev.id && !(x.staffIds && x.staffIds.length) && !x.staffId).length;
    if (open_ > 0) items.push({ id: "ev" + ev.id, t: `${eventTitle(ev)}: ${open_} ${open_ === 1 ? "place" : "places"} still to fill`, sub: "Choose your team", go: () => { dispatch({ type: "ACTIVE_EVENT", id: ev.id }); dispatch({ type: "V11_SET", patch: { bkView: { eventId: ev.id } } }); dispatch({ type: "TAB", tab: "bookings" }); } });
  });
  (state.teamInvites || []).filter(i => i.status === "pending").forEach(i => items.push({ id: "in" + i.id, t: "A team invite is waiting for you", sub: "Open your bookings", go: () => dispatch({ type: "TAB", tab: "bookings" }) }));
  return (
    <Sheet open onClose={onClose} title="Notifications">
      <div className="ff-ntf17">
        {items.length === 0 ? <p className="none">You are all caught up.</p> : <ul>{items.map(i => (
          <li key={i.id}><button type="button" onClick={() => { onClose(); i.go(); window.scrollTo(0, 0); }}><b>{i.t}</b><small>{i.sub}</small><S17I.ArrowRight size={16} /></button></li>))}</ul>}
        <button type="button" className="next" onClick={onNext}><Coin size={22} tier="gold" /><span>Your next steps</span><S17I.ArrowRight size={16} /></button>
      </div>
    </Sheet>
  );
}

