/* ---- Featured professionals --------------------------------------------- */
/** Featured professionals, from GET /user/network/featured. A card opens its
 *  public page; nothing featured, and the section stays out of the way. */
function HomeFeatured_unused() {
    const nav = useHomeNav();
    const navigate = useNavigate();
    const [featured, setFeatured] = useState(null);
    const [attempt, setAttempt] = useState(0);
    useEffect(() => {
        const ctrl = new AbortController();
        fetchFeatured(ctrl.signal).then(setFeatured, (err) => {
            if (!ctrl.signal.aborted)
                setFeatured({ error: err instanceof Error ? err.message : "Couldn't load the featured professionals." });
        });
        return () => ctrl.abort();
    }, [attempt]);
    if (Array.isArray(featured) && !featured.length)
        return null;
    const open = (p) => {
        navigate(`/${p.tag}`);
        window.scrollTo(0, 0);
    };
    return (<section className="ff-sect ff-feat17" id="ff-team" aria-labelledby="ff-feat17-h">
      <div className="ff-feat17-head">
        <h2 id="ff-feat17-h" className="ff-h1">Featured professionals</h2>
        <button type="button" className="ff-linkbtn" onClick={nav.goNetwork}>
          See everyone <ArrowRight size={13}/>
        </button>
      </div>
      {featured === null ? (<div role="status" aria-label="Loading featured professionals" className="flex gap-3 overflow-hidden">
          {[0, 1, 2, 3].map((i) => (<Skeleton key={i} width={CARD_W.player} style={{ aspectRatio: "5 / 7", height: "auto", borderRadius: 14 }}/>))}
        </div>) : "error" in featured ? (<p className="ff-body ff-muted m-0 text-[13px]" role="alert">
          {featured.error}{" "}
          <button type="button" className="font-semibold underline underline-offset-2" onClick={() => {
                setFeatured(null);
                setAttempt((n) => n + 1);
            }}>
            Try again
          </button>
        </p>) : (<HomeCarousel label="Featured professionals">
          {featured.map((p) => <PlayerTile key={p.id} person={p} onClick={() => open(p)}/>)}
        </HomeCarousel>)}
    </section>);
}
