/* ---- ported from v1.01: components/home/HomeFun.tsx ---- */

const COIN_SRC = (window.FF_IMG || {}).coin_gold;
/** The coin game, in its own file: it loads only when it's needed. */

/** v1.01: the coins between sections spin as the page scrolls. Each coin's
 *  turn comes from where it sits on screen - a slow full turn for every one
 *  and a half screens it travels - so it works whatever is doing the scrolling (the
 *  window, or a frame or panel the page sits in): scroll events are caught
 *  on the way down from the document. When scrolling stops, each coin eases
 *  round to face you. They only move while you scroll, so they turn even
 *  with Reduce Motion on (FireFlair's call - the coins are the point). */
function useCoinSpin(ref) {
    useEffect(() => {
        const root = ref.current;
        if (!root)
            return;
        let stopped = false;
        let raf = 0;
        let idle;
        // Per coin: an offset that keeps the turn continuous after it settles.
        const offset = new WeakMap();
        let list = [];
        const coins = () => {
            if (!list.length || list.some((el) => !el.isConnected) || root.querySelectorAll(".ff-coin3d .spin").length !== list.length)
                list = Array.from(root.querySelectorAll(".ff-coin3d .spin"));
            return list;
        };
        // All the reads first, then all the writes - one layout per frame - and
        // only for the coins on (or near) the screen.
        const nearCoins = () => {
            const vh = window.innerHeight || 800;
            const out = [];
            for (const el of coins()) {
                const r = (el.parentElement ?? el).getBoundingClientRect();
                if (r.bottom < -200 || r.top > vh + 200)
                    continue;
                const fromCentre = r.top + r.height / 2 - vh / 2;
                out.push({ el, a: (fromCentre * 360) / (vh * 1.5) + (offset.get(el) ?? 0) });
            }
            return out;
        };
        // If anything goes wrong, the coins just stay still - never a broken page.
        const safely = (fn) => {
            if (stopped)
                return;
            try {
                fn();
            }
            catch {
                stop();
            }
        };
        const write = () => safely(() => {
            raf = 0;
            for (const { el, a } of nearCoins()) {
                el.style.transition = "none";
                el.style.transform = `rotateY(${a.toFixed(1)}deg)`;
            }
        });
        const settle = () => safely(() => {
            for (const { el, a } of nearCoins()) {
                const face = Math.round(a / 360) * 360;
                offset.set(el, (offset.get(el) ?? 0) + face - a);
                el.style.transition = "transform 1.4s cubic-bezier(.22,.7,.2,1)";
                el.style.transform = `rotateY(${face}deg)`;
            }
        });
        const onScroll = () => {
            if (!raf)
                raf = requestAnimationFrame(write);
            window.clearTimeout(idle);
            idle = window.setTimeout(settle, 220);
        };
        const stop = () => {
            stopped = true;
            document.removeEventListener("scroll", onScroll, { capture: true });
            window.removeEventListener("resize", onScroll);
            window.clearTimeout(idle);
            if (raf)
                cancelAnimationFrame(raf);
        };
        // Starts once the page has loaded and the browser is idle, so it never
        // competes with the page itself.
        const cancelStart = afterLoad(() => safely(() => {
            document.addEventListener("scroll", onScroll, { capture: true, passive: true });
            window.addEventListener("resize", onScroll);
        }));
        return () => {
            cancelStart();
            stop();
        };
    }, [ref]);
}
/** Runs `fn` once the page has loaded and the browser has a quiet moment.
 *  Returns a cancel. */
function afterLoad(fn) {
    let handle;
    let cancelled = false;
    const idle = () => {
        if (cancelled)
            return;
        const w = window;
        handle = w.requestIdleCallback ? w.requestIdleCallback(fn, { timeout: 2000 }) : window.setTimeout(fn, 300);
    };
    if (document.readyState !== "loading")
        idle();
    else {
        document.addEventListener("DOMContentLoaded", idle, { once: true });
        window.addEventListener("load", idle, { once: true });
    }
    return () => {
        cancelled = true;
        window.removeEventListener("load", idle);
        const w = window;
        if (handle !== undefined)
            (w.cancelIdleCallback ?? window.clearTimeout)(handle);
    };
}
/** Whether the coin game should load: near the screen, after the page has
 *  loaded, and not on a slow or data-saving connection. */
function useGameReady(box) {
    const [ready, setReady] = useState(false);
    useEffect(() => {
        const el = box.current;
        if (!el || typeof IntersectionObserver === "undefined")
            return;
        const conn = navigator.connection;
        if (conn?.saveData || /(^|-)2g$/.test(conn?.effectiveType ?? ""))
            return;
        let near = false;
        let loaded = false;
        const check = () => near && loaded && setReady(true);
        const io = new IntersectionObserver(([e]) => {
            if (e?.isIntersecting) {
                near = true;
                io.disconnect();
                check();
            }
        }, { rootMargin: "600px 0px" });
        io.observe(el);
        const cancel = afterLoad(() => {
            loaded = true;
            check();
        });
        return () => {
            io.disconnect();
            cancel();
        };
    }, [box]);
    return ready;
}
/** Thin gold discs stacked behind the faces give the coin its edge. */
