/* ---- ported from v1.01: components/home/CoinDrop.tsx ---- */

/* v1.01: the coin drop at the end of Home. Its own file so it loads on its
 * own, only when it's needed (see HomeJoin in HomeFun.tsx) - it never slows
 * the page down. */
const DROP_COINS = 16;
/** Gold, silver and platinum coins. */
const DROP_SRC = [(window.FF_IMG || {}).coin_gold, (window.FF_IMG || {}).coin_silver, FF_VIP_LOGO];
/** Points under the boxes, left to right. */
const BIN_POINTS = [5, 10, 15, 20];
const GRAVITY = 0.55;
/** Each coin bounces at most this many times, then it settles. */
const BOUNCE_LIMIT = 5;
const MAX_PULL = 110;
/** The machine, worked out from the stage size: the coin box on the right
 *  behind a barrier, a soft curve across the top-right that turns coins
 *  launched straight up over the barrier, and four deep boxes on the floor. */
function machine(w, h) {
    const hopper = Math.max(100, Math.min(150, w * 0.3));
    const wall = 8;
    const bx = w - hopper - wall;
    const btop = h - Math.min(h * 0.46, 210);
    const R = Math.min(hopper + 60, h * 0.45);
    return { hopper, wall, bx, btop, R, cx: w - R, cy: R, binW: bx / 4, divTop: h - 88 };
}
/** Keeps a coin out of a solid rectangle, bouncing it off the side it hit. */
function hitRect(c, x0, y0, x1, y1, e) {
    const px = Math.max(x0, Math.min(c.x, x1));
    const py = Math.max(y0, Math.min(c.y, y1));
    let nx = c.x - px;
    let ny = c.y - py;
    const d = Math.hypot(nx, ny);
    if (d >= c.r)
        return;
    if (d > 0) {
        nx /= d;
        ny /= d;
        c.x = px + nx * c.r;
        c.y = py + ny * c.r;
    }
    else {
        // Centre inside: out through the nearest of the top and the sides.
        const top = c.y - y0;
        const left = c.x - x0;
        const right = x1 - c.x;
        if (top <= left && top <= right)
            [nx, ny, c.y] = [0, -1, y0 - c.r];
        else if (left < right)
            [nx, ny, c.x] = [-1, 0, x0 - c.r];
        else
            [nx, ny, c.x] = [1, 0, x1 + c.r];
    }
    const vn = c.vx * nx + c.vy * ny;
    if (vn < 0) {
        const settled = c.n >= BOUNCE_LIMIT;
        if (-vn > 0.8)
            c.n++;
        const k = settled ? 0 : e;
        c.vx -= (1 + k) * vn * nx;
        c.vy -= (1 + k) * vn * ny;
        if (settled) {
            c.vx *= 0.6;
            c.va *= 0.6;
        }
    }
}
/** Taps and flicks on these don't throw coins. */
const isControl = (t) => t instanceof Element && !!t.closest("button, a");
/** v1.01: the coin drop, filling the Join box at the end of Home - the Join
 *  words are its background. Flick the coins up out of the box on the right
 *  (or pull up past the end of the page, or keep scrolling down on a
 *  computer): two or three at a time fly up, bounce off the curve, over the
 *  barrier and down into the boxes - 5, 10, 15 or 20. Reset puts them all
 *  back, and so does a refresh: nothing is saved. The page's own bounce is
 *  off on Home, so the pull bounces here and the bottom bar stays put.
 *  Simple physics - it only runs while something is moving. */
function CoinDrop({ area }) {
    const stage = useRef(null);
    const els = useRef([]);
    const labels = useRef([]);
    const api = useRef(null);
    const [size, setSize] = useState({ w: 360, h: 520 });
    // The stage's size drives the drawing; the physics reads it live.
    useLayoutEffect(() => {
        const box = stage.current;
        if (!box)
            return;
        const read = () => setSize({ w: box.clientWidth, h: box.clientHeight });
        read();
        const ro = new ResizeObserver(read);
        ro.observe(box);
        return () => ro.disconnect();
    }, []);
    useEffect(() => {
        const box = stage.current;
        const zone = area.current;
        if (!box || !zone)
            return;
        let w = box.clientWidth;
        let h = box.clientHeight;
        let m = machine(w, h);
        let raf = 0;
        let pull = 0;
        let lastLaunch = 0;
        // Every coin in the box on the right, stacked from the floor - or, for
        // Reset, dropped in from above.
        const place = (dropIn = false) => {
            const left = m.bx + m.wall;
            const perRow = Math.max(2, Math.floor(m.hopper / 32));
            const gap = m.hopper / perRow;
            return Array.from({ length: DROP_COINS }, (_, k) => {
                const r = 14 + (k % 3) * 2;
                const row = Math.floor(k / perRow);
                const col = k % perRow;
                return {
                    x: left + gap * col + gap / 2 + (row % 2 ? 3 : -3),
                    y: h - r - row * 26 - (dropIn ? m.btop * 0.6 + k * 9 : 0),
                    n: 0, cd: 0, vx: 0, vy: 0, a: (k * 47) % 360, va: dropIn ? (k % 2 ? 6 : -6) : 0, r, flying: false, bin: null,
                };
            });
        };
        let coins = place();
        const draw = () => {
            coins.forEach((c, k) => {
                const el = els.current[k];
                if (!el)
                    return;
                el.style.width = el.style.height = `${c.r * 2}px`;
                el.style.transform = `translate(${(c.x - c.r).toFixed(1)}px, ${(c.y - c.r).toFixed(1)}px) rotate(${c.a.toFixed(1)}deg)`;
            });
        };
        const flash = (bin) => {
            const el = labels.current[bin];
            if (!el)
                return;
            el.classList.remove("hit");
            void el.offsetWidth;
            el.classList.add("hit");
        };
        const step = () => {
            let moving = pull > 0;
            for (const c of coins) {
                c.vy += GRAVITY;
                c.x += c.vx;
                c.y += c.vy;
                c.a += c.va;
                c.va *= 0.99;
                if (c.cd > 0)
                    c.cd--;
                // The curve across the top-right, and the flat top to its left.
                if (c.x > m.cx && c.y < m.cy) {
                    const dx = c.x - m.cx;
                    const dy = c.y - m.cy;
                    const d = Math.hypot(dx, dy);
                    const lim = m.R - c.r;
                    if (d > lim) {
                        const nx = dx / d;
                        const ny = dy / d;
                        c.x = m.cx + nx * lim;
                        c.y = m.cy + ny * lim;
                        const vn = c.vx * nx + c.vy * ny;
                        if (vn > 0) {
                            const k = c.n >= BOUNCE_LIMIT ? 1 : 1.8;
                            if (vn > 0.8)
                                c.n++;
                            c.vx -= k * vn * nx;
                            c.vy -= k * vn * ny;
                        }
                    }
                }
                else if (c.y < c.r) {
                    c.y = c.r;
                    if (c.vy < 0) {
                        if (c.n >= BOUNCE_LIMIT)
                            c.vy = 0;
                        else {
                            c.vy = -c.vy * 0.5;
                            if (c.vy > 0.4)
                                c.n++;
                        }
                    }
                }
                // Side walls and the floor.
                const wallBounce = (dir) => {
                    if (Math.abs(c.vx) > 0.8 && c.n < BOUNCE_LIMIT) {
                        c.vx = dir * Math.abs(c.vx) * 0.5;
                        c.n++;
                    }
                    else
                        c.vx = 0;
                };
                if (c.x < c.r) {
                    c.x = c.r;
                    wallBounce(1);
                }
                if (c.x > w - c.r) {
                    c.x = w - c.r;
                    wallBounce(-1);
                }
                if (c.y > h - c.r) {
                    c.y = h - c.r;
                    if (Math.abs(c.vy) > 1.4 && c.n < BOUNCE_LIMIT) {
                        c.vy = -c.vy * 0.3;
                        c.n++;
                    }
                    else
                        c.vy = 0;
                    c.vx *= 0.8;
                    c.va *= 0.8;
                }
                // The barrier, and the dividers between the boxes.
                hitRect(c, m.bx, m.btop, m.bx + m.wall, h, 0.35);
                for (let k = 1; k < 4; k++)
                    hitRect(c, m.binW * k - 2, m.divTop, m.binW * k + 2, h, 0.2);
                // Landed in a box.
                if (c.flying && c.x < m.bx && c.y > m.divTop - c.r * 0.5 && c.vy >= 0) {
                    c.flying = false;
                    c.bin = Math.max(0, Math.min(3, Math.floor(c.x / m.binW)));
                    flash(c.bin);
                }
                // In a box, coins settle quickly instead of rolling about.
                if (c.bin !== null && c.y > m.divTop) {
                    c.vx *= 0.7;
                    c.va *= 0.7;
                }
                // Fell back into the coin box.
                if (c.flying && c.x > m.bx + m.wall && c.y > m.btop && c.vy >= 0)
                    c.flying = false;
                if (Math.abs(c.vx) > 0.04 || Math.abs(c.vy) > 0.04 || Math.abs(c.va) > 0.08)
                    moving = true;
            }
            // Coins push each other apart, so they pile instead of overlapping.
            for (let i = 0; i < coins.length; i++) {
                for (let j = i + 1; j < coins.length; j++) {
                    const a = coins[i];
                    const b = coins[j];
                    const dx = b.x - a.x;
                    const dy = b.y - a.y;
                    const min = (a.r + b.r) * 0.92;
                    const d2 = dx * dx + dy * dy;
                    if (d2 > 0 && d2 < min * min) {
                        const d = Math.sqrt(d2);
                        const push = (min - d) / 2;
                        const nx = dx / d;
                        const ny = dy / d;
                        // Hitting another coin counts as a bounce for each; settled coins just stop.
                        for (const q of [a, b]) {
                            if (q.n >= BOUNCE_LIMIT) {
                                q.vx *= 0.5;
                                q.vy *= 0.5;
                                q.va *= 0.5;
                            }
                            else if (q.cd <= 0 && Math.hypot(q.vx, q.vy) > 1.5) {
                                q.n++;
                                q.cd = 10;
                            }
                        }
                        a.x -= nx * push;
                        a.y -= ny * push;
                        b.x += nx * push;
                        b.y += ny * push;
                    }
                }
            }
            // ...and the walls, floor, barrier and dividers still hold after that.
            for (const c of coins) {
                c.x = Math.max(c.r, Math.min(w - c.r, c.x));
                // A coin in the box stays in it until it's thrown (so Reset can't spill any).
                if (c.bin === null && !c.flying)
                    c.x = Math.max(m.bx + m.wall + c.r, c.x);
                c.y = Math.min(h - c.r, c.y);
                hitRect(c, m.bx, m.btop, m.bx + m.wall, h, 0);
                for (let k = 1; k < 4; k++)
                    hitRect(c, m.binW * k - 2, m.divTop, m.binW * k + 2, h, 0);
            }
            draw();
            raf = moving ? requestAnimationFrame(step) : 0;
        };
        const run = () => {
            if (!raf)
                raf = requestAnimationFrame(step);
        };
        /** A flick: two or three coins from the top of the box fly up, the rest
         *  of the box jiggles. `strength` around 1 just clears the barrier. */
        const launch = (strength) => {
            const now = performance.now();
            if (now - lastLaunch < 420)
                return;
            lastLaunch = now;
            const inBox = coins.filter((c) => c.bin === null && c.x > m.bx + m.wall).sort((a, b) => a.y - b.y);
            const n = Math.min(inBox.length, 2 + (Math.random() < 0.45 ? 1 : 0));
            const base = Math.sqrt(2 * GRAVITY * h * 0.82);
            inBox.forEach((c) => { c.n = 0; c.cd = 0; });
            inBox.slice(0, n).forEach((c) => {
                c.vy = -base * strength * (0.74 + Math.random() * 0.42);
                c.vx = -Math.random() * 1.4;
                c.va = (Math.random() - 0.5) * 26;
                c.flying = true;
            });
            inBox.slice(n).forEach((c) => {
                c.vy -= 1.2 + Math.random() * 1.6;
                c.va += (Math.random() - 0.5) * 8;
            });
            run();
        };
        api.current = {
            reset: () => {
                coins = place(true);
                run();
            },
        };
        draw();
        // The pull past the end of the page: a little stretch, then a flick.
        const atBottom = () => window.innerHeight + window.scrollY >= document.documentElement.scrollHeight - 2;
        const setPull = (v, spring = false) => {
            pull = Math.max(0, Math.min(MAX_PULL, v));
            // The whole box lifts, then springs back.
            const el = zone;
            el.style.transition = spring ? "transform .55s cubic-bezier(.34,1.56,.64,1)" : "none";
            el.style.transform = `translateY(${-pull}px)`;
        };
        let release;
        const letGo = () => {
            if (pull > 20)
                launch(Math.min(1.25, 0.9 + pull / 300));
            setPull(0, true);
        };
        const flickStrength = (dy, ms) => dy > 12 ? Math.max(0.85, Math.min(1.3, 0.85 + (dy / Math.max(16, ms)) * 0.3)) : 1;
        // Touch: a flick that starts in the box (not on its buttons).
        let lastY = 0;
        let flick = null;
        const onStart = (e) => {
            lastY = e.touches[0].clientY;
            flick = zone.contains(e.target) && !isControl(e.target) ? { y: lastY, t: performance.now() } : null;
        };
        const onMove = (e) => {
            const y = e.touches[0].clientY;
            const dy = lastY - y;
            lastY = y;
            if (!atBottom() || (dy <= 0 && pull === 0))
                return;
            setPull(pull + dy * 0.5);
        };
        const onEnd = () => {
            // A tap or an upward flick throws; a swipe down (scrolling back up) doesn't.
            if (flick && flick.y - lastY > -12)
                launch(flickStrength(flick.y - lastY, performance.now() - flick.t));
            flick = null;
            letGo();
        };
        const onWheel = (e) => {
            if (e.deltaY <= 0 || !atBottom())
                return;
            setPull(pull + e.deltaY * 0.2);
            window.clearTimeout(release);
            release = window.setTimeout(letGo, 140);
        };
        // Mouse: click, or drag up and let go - the faster, the higher.
        let down = null;
        const onDown = (e) => {
            if (e.pointerType !== "touch" && !isControl(e.target))
                down = { y: e.clientY, t: performance.now() };
        };
        const onUp = (e) => {
            if (!down || e.pointerType === "touch")
                return;
            launch(flickStrength(down.y - e.clientY, performance.now() - down.t));
            down = null;
        };
        const onResize = () => {
            const nw = box.clientWidth;
            const nh = box.clientHeight;
            if (nw === w && nh === h)
                return;
            for (const c of coins) {
                c.x *= nw / w;
                c.y = nh - (h - c.y);
            }
            w = nw;
            h = nh;
            m = machine(w, h);
            run();
        };
        const ro = new ResizeObserver(onResize);
        ro.observe(box);
        // Home's bounce happens here, not on the whole page.
        const html = document.documentElement;
        const before = [html.style.overscrollBehaviorY, document.body.style.overscrollBehaviorY];
        html.style.overscrollBehaviorY = "none";
        document.body.style.overscrollBehaviorY = "none";
        window.addEventListener("touchstart", onStart, { passive: true });
        window.addEventListener("touchmove", onMove, { passive: true });
        window.addEventListener("touchend", onEnd, { passive: true });
        window.addEventListener("touchcancel", onEnd, { passive: true });
        window.addEventListener("wheel", onWheel, { passive: true });
        zone.addEventListener("pointerdown", onDown);
        zone.addEventListener("pointerup", onUp);
        return () => {
            html.style.overscrollBehaviorY = before[0];
            document.body.style.overscrollBehaviorY = before[1];
            window.removeEventListener("touchstart", onStart);
            window.removeEventListener("touchmove", onMove);
            window.removeEventListener("touchend", onEnd);
            window.removeEventListener("touchcancel", onEnd);
            window.removeEventListener("wheel", onWheel);
            zone.removeEventListener("pointerdown", onDown);
            zone.removeEventListener("pointerup", onUp);
            ro.disconnect();
            window.clearTimeout(release);
            if (raf)
                cancelAnimationFrame(raf);
            api.current = null;
        };
    }, [area]);
    const m = machine(size.w, size.h);
    // The quarter curve across the top-right, as drawn.
    const curve = `M ${m.cx.toFixed(1)} 2 A ${(m.R - 2).toFixed(1)} ${(m.R - 2).toFixed(1)} 0 0 1 ${(size.w - 2).toFixed(1)} ${m.cy.toFixed(1)}`;
    return (<>
      <div className="ff-drop" aria-hidden="true">
        <div className="ff-drop-stage" ref={stage}>
          <svg className="ff-drop-art" width={size.w} height={size.h} viewBox={`0 0 ${size.w} ${size.h}`}>
            <path d={curve} className="curve"/>
            {BIN_POINTS.map((_, k) => (<rect key={k} x={m.binW * k + 3} y={m.divTop} width={m.binW - 6} height={size.h - m.divTop} rx="5" className="bin"/>))}
            {[1, 2, 3].map((k) => (<rect key={k} x={m.binW * k - 2} y={m.divTop} width="4" height={size.h - m.divTop} rx="2" className="divider"/>))}
            <rect x={m.bx} y={m.btop} width={m.wall} height={size.h - m.btop} rx="3" className="barrier"/>
            <rect x={m.bx + m.wall} y={m.btop} width={m.hopper} height={size.h - m.btop} className="hopper"/>
            <g className="nudge" transform={`translate(${m.bx + m.wall + m.hopper / 2} ${m.btop - 22})`}>
              <path d="M-9 6 0 -3 9 6"/>
              <path d="M-9 14 0 5 9 14"/>
            </g>
          </svg>
          {Array.from({ length: DROP_COINS }, (_, k) => (<img key={k} ref={(el) => {
                els.current[k] = el;
            }} className="ff-drop-coin" src={DROP_SRC[k % DROP_SRC.length]} alt="" draggable={false}/>))}
        </div>
        <div className="ff-drop-points">
          {BIN_POINTS.map((p, k) => (<span key={p} ref={(el) => {
                labels.current[k] = el;
            }} style={{ left: `${((m.binW * k + m.binW / 2) / size.w) * 100}%` }}>
              {p}
            </span>))}
        </div>
      </div>
      <button type="button" className="ff-drop-reset" onClick={() => api.current?.reset()} aria-label="Put the coins back in the box">
        <RotateCcw size={13} strokeWidth={2.4}/> Reset
      </button>
    </>);
}

/* ---- v1.01 hero: Welcome to FireFlair, Get seen. Get booked. ---- */
function HomeSearch() {
  const { dispatch } = useStore();
  const nav = useHomeNav();
  const [val, setVal] = useState("");
  const submit = () => { dispatch({ type: "NET_QUERY", q: val.trim() }); nav.goNetwork(); };
  return (
    <form className="ff-frame ff-ai ff-ffai-tint hero bare ff-hero-search" role="search" onSubmit={(e) => { e.preventDefault(); submit(); }}>
      <div className="ff-ai-row" style={{ alignItems: "center" }}>
        <span className="ff-ai-tag" aria-hidden="true"><Coin size={20} tier="gold" /></span>
        <input type="search" className="ff-input ff-ai-in min-w-0 flex-1" aria-label="Search FireFlair" placeholder="Search people, skills, locations…" value={val} onChange={(e) => setVal(e.target.value)} />
        <button type="submit" className="ff-ai-send" aria-label="Search" title="Search"><Search size={16} strokeWidth={2} /></button>
      </div>
    </form>
  );
}
function HomeHero101() {
  const { state } = useStore();
  const nav = useHomeNav();
  const mine = state.role === "team" && state.profile.live;
  return (
    <section className="ff-hero18" aria-labelledby="ff-hero17-h" id="ff-hero">
      <div className="ff-hero18-img">
        {IMGS.hero ? <img className="ff-hero18-photo" src={IMGS.hero} srcSet={IMGS.hero_sm ? `${IMGS.hero_sm} 900w, ${IMGS.hero} 1800w` : undefined} sizes="(min-width:900px) 760px, 100vw" alt="" decoding="async" /> : <HomeScene kind="bar" />}
        <div className="ff-hero18-fade" aria-hidden="true" />
        <span className="ff-hero18-shadow" aria-hidden="true" />
        <span className="ff-hero18-coin refl" aria-hidden="true"><Coin size={160} tier="gold" /></span>
        <span className="ff-hero18-coin ff-hero17-coin"><Coin size={160} tier="gold" /></span>
      </div>
      <div className="ff-hero18-in">
        <h1 id="ff-hero17-h" className="ff-hero17-h ff-hero-h101">Welcome to FireFlair</h1>
        <p className="ff-hero-sub101">Get seen. Get booked.</p>
        <div className="ff-hero17-cta">
          <ShineButton onClick={nav.goProfile}><User size={15} /> {mine ? "My Profile Card" : "Create your Profile Card"}</ShineButton>
        </div>
        <div className="ff-hero17-ai"><HomeSearch /></div>
      </div>
    </section>
  );
}

/* ---- Once the card is shared: what's on it, the network and reviews ---- */
function WelcomeBack101() {
  const { state, dispatch } = useStore();
  const shown = CARD_CATEGORIES.reduce((n, k) => n + featuredCount(state.profile, k), 0);
  const netCount = myNetwork(state, state.directory).list.length;
  const myReviews = (state.reviews || []).filter((r) => r.aboutId === "me").length;
  const first = (state.profile.name || "").trim().split(" ")[0];
  return (
    <div className="ff-frame ff-welcome17" style={{ padding: 14 }}>
      <Corners />
      <h2 className="ff-h2" style={{ margin: "0 0 10px" }}>{`Welcome back${first ? `, ${first}` : ""}`}</h2>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 8 }}>
        {[["On card", shown, "profile"], ["Network", netCount, "network"], ["Reviews", myReviews, "profile"]].map(([l, v, tab]) => (
          <button key={l} className="ff-frame" style={{ padding: "10px 12px", textAlign: "left" }} onClick={() => { dispatch({ type: "TAB", tab, route: "home" }); window.scrollTo(0, 0); }}>
            <div className="ff-display" style={{ fontSize: 22 }}>{v}</div>
            <div className="ff-label">{l}</div>
          </button>
        ))}
      </div>
    </div>
  );
}

