/* ---- Beta and Join -------------------------------------------------------- */
function HireBeta({ name }) {
  const [open, setOpen] = useState(false);
  return (
    <section className="ff-sect" id="ff-beta" aria-labelledby="ff-beta11-h">
      <div className="ff-beta-box">
        <span className="ff-beta-tag">Beta {BETA_VERSION}</span>
        <h2 id="ff-beta11-h" className="ff-beta-h">We're in beta - please give us feedback.</h2>
        <p className="ff-beta-t">Tell us what works and what you'd like next. It goes straight to the people building {name}.</p>
        <Button onClick={() => setOpen(true)}>Give feedback</Button>
      </div>
      <BetaFeedbackSheet open={open} onClose={() => setOpen(false)} />
    </section>
  );
}

function HireJoin({ kind }) {
  const { state } = useStore();
  const nav = useHireNav();
  const box = useRef(null);
  const game = useGameReady(box);
  const joined = !!(state.company && state.company.joinedAt);
  const c = kind === "party"
    ? { h: "Plan your event", t: "Create your Event Card in a minute, and we'll take it from there.", b: "Plan your event", go: nav.toEvent, icon: Popper11 }
    : joined
      ? { h: "Your FF Business", t: "Create an Event Card, choose your staff, then add their shift details.", b: "Choose your team", go: nav.toEvent, icon: CalDays11 }
      : { h: "Join FF Business", t: "Your Company Card, so you can start booking.", b: "Join now", go: nav.toProfile, icon: Briefcase };
  return (
    <section className="ff-sect ff-join" aria-labelledby="ff-join11-h">
      <div className="ff-join-box ff-game" ref={box}>
        <div className="ff-join-in">
          <Coin size={56} tier={kind === "party" ? "bronze" : "silver"} />
          <h2 id="ff-join11-h" className="ff-join-h">{c.h}</h2>
          <p className="ff-join-t">{c.t}</p>
          <ShineButton onClick={c.go}><c.icon size={15} /> {c.b}</ShineButton>
        </div>
        {game && <QuietBoundary><Suspense fallback={null}><CoinDrop area={box} /></Suspense></QuietBoundary>}
      </div>
    </section>
  );
}


/* ==== The card family: every kind of card, stacked like a hand of cards ==== */
function CfImg11(name) { return (window.FF_IMG || {})[name] || ""; }
function CfPlate11({ children }) { return <span className="cf-plate">{children}</span>; }
function CfProfile11({ photo, name, role, tier }) {
  return (<div className="cf-face cf-profile">
    <div className="ph" style={{ backgroundImage: `url(${photo})` }} />
    <div className="tx"><b>{name}</b><small>{role}</small></div>
    <span className="coin"><Coin size={26} tier={tier} flat /></span>
    <CfPlate11>Profile Card</CfPlate11>
  </div>);
}
function CfCompany11({ banner, name, kind, area }) {
  return (<div className="cf-face cf-company">
    <div className="ph" style={{ backgroundImage: `url(${banner})` }} />
    <span className="mk"><I11.Briefcase size={20} strokeWidth={1.6} /></span>
    <div className="tx"><b>{name}</b><small>{kind}</small><em><I11.MapPin size={10} /> {area}</em></div>
    <CfPlate11>Company Card</CfPlate11>
  </div>);
}
function CfService11({ tone, tier, title, line }) {
  return (<div className={`cf-face cf-service ${tone}`}>
    <span className="rb">Service Card</span>
    <span className="coin"><Coin size={28} tier={tone === "bronze" ? "bronze" : tone === "silver" ? "silver" : "gold"} flat /></span>
    <div className="tx"><i>{tier} · FF Party</i><b>{title}</b><small>{line}</small></div>
    <span className="ln"><I11.Sparkles size={12} /> Includes bar, staff and drinks</span>
  </div>);
}
function CfEvent11({ photo, title, when, where }) {
  return (<div className="cf-face cf-event" style={{ backgroundImage: `url(${photo})` }}>
    <span className="dt"><I11.CalendarDays size={11} /> {when}</span>
    <div className="tx"><b>{title}</b><small><I11.MapPin size={10} /> {where}</small></div>
    <CfPlate11>Event Card</CfPlate11>
  </div>);
}
function CfReview11({ text, from, to }) {
  return (<div className="cf-face cf-review">
    <span className="st">{[0, 1, 2, 3, 4].map(i => <I11.Star key={i} size={13} fill="currentColor" strokeWidth={0} />)}</span>
    <p>“{text}”</p>
    <div className="by"><span className="av">{from[0]}</span><small>{from} <i>for</i> {to}</small></div>
    <CfPlate11>Review Card</CfPlate11>
  </div>);
}
function CardFamily11() {
  const SV = (typeof PARTY_SERVICES !== "undefined" && PARTY_SERVICES) || [];
  const sv = (i, d) => SV[i] || d;
  const g = sv(2, { title: "Cocktail masterclass", tagline: "A hosted class for your guests" }), s = sv(1, { title: "Mobile bar", tagline: "Bartender and bar, fully set up" }), b = sv(0, { title: "Bartender hire", tagline: "A skilled bartender for the night" });
  const stacks = [
    { k: "profile", t: "Profile Cards", d: "People, with their skills and reviews.", cards: [
      <CfProfile11 key="a" photo={CfImg11("face_you")} name="Sophie Hart" role="Cocktail Bartender" tier="gold" />,
      <CfProfile11 key="b" photo={CfImg11("dream_flair_jobs")} name="Marcus Bell" role="Flair Bartender" tier="silver" />,
      <CfProfile11 key="c" photo={CfImg11("dream_after_dark")} name="Ines Moreau" role="Bar Manager" tier="gold" />] },
    { k: "company", t: "Company Cards", d: "Businesses, bars and venues.", cards: [
      <CfCompany11 key="a" banner={CfImg11("dream_after_dark")} name="The Loft Lounge" kind="Cocktail bar & private events" area="North London" />,
      <CfCompany11 key="b" banner={CfImg11("dream_food_festivals_markets")} name="Saffron Catering" kind="Wedding & event catering" area="West London" />,
      <CfCompany11 key="c" banner={CfImg11("dream_international_events")} name="Northbank Events" kind="Event agency & production" area="London" />] },
    { k: "service", t: "Service Cards", d: "The shifts and packages you book.", cards: [
      <CfService11 key="a" tone="gold" tier="Gold" title={g.title} line={g.tagline} />,
      <CfService11 key="b" tone="silver" tier="Silver" title={s.title} line={s.tagline} />,
      <CfService11 key="c" tone="bronze" tier="Bronze" title={b.title} line={b.tagline} />] },
    { k: "cocktail", t: "Cocktail Cards", d: "Signature drinks, with the recipe.", cards: [
      <img key="a" className="cf-face cf-cock" src={CfImg11("cocktail_0")} alt="Old Fashioned cocktail card" loading="eager" decoding="async" />,
      <img key="b" className="cf-face cf-cock" src={CfImg11("cocktail_1")} alt="French Martini cocktail card" loading="eager" decoding="async" />,
      <img key="c" className="cf-face cf-cock" src={CfImg11("cocktail_2")} alt="Piña Colada cocktail card" loading="eager" decoding="async" />] },
    { k: "event", t: "Event Cards", d: "Every booking starts here.", cards: [
      <CfEvent11 key="a" photo={CfImg11("dream_music_festivals")} title="Summer Festival Bar" when="Sat 12 Jun" where="Victoria Park" />,
      <CfEvent11 key="b" photo={CfImg11("dream_flair_jobs")} title="Spring Launch Party" when="Sat 20 Mar" where="The Loft, Enfield" />,
      <CfEvent11 key="c" photo={CfImg11("dream_yacht_jobs")} title="Yacht Reception" when="Fri 4 Jul" where="St Katharine Docks" />] },
    { k: "review", t: "Review Cards", d: "Reputation, earned one event at a time.", cards: [
      <CfReview11 key="a" text="Ran the bar at our launch night without a single hiccup." from="Ava" to="Sam" />,
      <CfReview11 key="b" text="Fast, clean and brilliant with the guests." from="Jo" to="Marcus" />,
      <CfReview11 key="c" text="Our guests are still talking about the cocktails." from="Priya" to="Sophie" />] },
  ];
  return (
    <section className="ff-sect ff-cf" id="ff-cards" aria-labelledby="ff-cf-h">
      <h2 id="ff-cf-h" className="ff-h1">The card family</h2>
      <p className="ff-cf-lede">Everything on FireFlair is a card.</p>
      <div className="ff-cf-board">
        {stacks.map(st => (
          <figure key={st.k} className={`ff-cf-cell ${st.k}`}>
            <div className="ff-cf-stack" aria-hidden="true">
              <div className="ff-cf-card c3">{st.cards[2]}</div>
              <div className="ff-cf-card c2">{st.cards[1]}</div>
              <div className="ff-cf-card c1">{st.cards[0]}</div>
            </div>
            <figcaption><b>{st.t}</b><span>{st.d}</span></figcaption>
          </figure>
        ))}
      </div>
    </section>
  );
}

