function HowBooking17({ kind = "team" }) {
  const hire = useHireNav();
  const home = useHomeNav();
  const list = HB17[kind] || HB17.team;
  const pics = HBM17[kind] || HBM17.team;
  return (
    <section className="ff-sect ff-hb17" id="ff-how" aria-labelledby="ff-hb17-h">
      <h2 id="ff-hb17-h" className="ff-h1">How a booking works</h2>
      <ol className="ff-hb17-row">
        {list.map(([Ic, t, x], i) => (
          <React.Fragment key={t}>
            {i > 0 && <li className="arr" aria-hidden="true"><ArrowRight size={22} strokeWidth={2.2} /></li>}
            <li className={"card" + (i % 2 ? " flip" : "")}><span className="n">{i + 1}</span><span className="pic" aria-hidden="true"><HBMini17 k={pics[i]} /></span><span className="tx"><span className="ic"><Ic size={18} strokeWidth={1.7} /></span><b>{t}</b><span className="t">{x}</span></span></li>
          </React.Fragment>
        ))}
      </ol>
      {kind === "party" && (
        <div className="ff-hb17-rule" role="group" aria-label="The 24-hour rule">
          <span className="h"><Clock size={16} strokeWidth={1.8} /> The 24-hour rule</span>
          <ol>
            <li><b>24 hours to confirm.</b> The people you choose get the shift first, and it stays theirs for 24 hours.</li>
            <li><b>Then it opens up.</b> If someone is unavailable or does not reply in time, the shift is shared with every suitable person on the network.</li>
            <li><b>We find your team.</b> FireFlair finds suitable people who are free and presents them to you.</li>
          </ol>
        </div>
      )}
      {kind === "staff" && (
        <div className="ff-hb17-rule gold" role="group" aria-label="Last-minute shifts">
          <span className="h"><Clock size={16} strokeWidth={1.8} /> Last-minute shifts <i>Gold</i></span>
          <p>Shifts starting within 24 hours go out to everyone on the network straight away, so they are filled as fast as possible.</p>
        </div>
      )}
      <div className="ff-hb17-cta">
        {kind === "team" ? <Button onClick={home.goProfile}><User size={14} /> Create your Profile Card</Button> : <ShineButton onClick={hire.toEvent}><Popper11 size={15} /> Plan your event</ShineButton>}
      </div>
    </section>
  );
}

function withCoins(list) { return list.flatMap((s, i) => (i ? [<CoinDivider key={`coin-${i}`} />, s] : [s])); }

function StaffHome11() {
  const { state, dispatch } = useStore();
  DIR = useDirectory();
  const root = useRef(null);
  useCoinSpin(root);
  useEffect(() => { if (state.route === "eventNew") { dispatch({ type: "GO", route: "staffHome" }); dispatch({ type: "V11_SET", patch: { bkView: { mode: "new", open: "event" } } }); dispatch({ type: "TAB", tab: "bookings" }); } }, [state.route]);
  return (
    <div className="ff-home ff-home11 staff" ref={root}>
      <div className="ff-home17">
        <HireHero kind="staff" />
        {withCoins([
          <DiscoverHub11 key="discover" cats={DX_BIZ} kind="staff" />,
          <HowBooking17 key="how" kind="staff" />,
          <GuideQuestions11 key="guide" kind="staff" />,
          <Journal17 key="journal" kind="staff" />,
          <React.Fragment key="why"><WhyFlair17 kind="staff" /><OurDream17 kind="staff" /></React.Fragment>,
          <HireBeta key="beta" name="FF Business" />,
          <HireJoin key="join" kind="staff" />,
        ])}
      </div>
    </div>
  );
}

/* ---- FF Party: a basic how-it-works home for people planning a party ------ */
const PARTY_STEPS11 = [
  { icon: CalDays11, title: "Your event", text: "The date, the place, private or corporate, and how many guests." },
  { icon: Sparkles, title: "Your service", text: "A FireFlair Service Card that suits your party, or one of your own." },
  { icon: Users, title: "Your staff", text: "Bartenders who have signed up to it, or a bar company and its team." },
  { icon: MessageSquare, title: "We confirm on WhatsApp", text: "FireFlair confirms everything with you and your staff." },
];
function PartyHow() {
  const nav = useHireNav();
  return (
    <section className="ff-sect ff-hw11 party" id="ff-how-book" aria-labelledby="ff-phw11-h">
      <div className="ff-hw11-box">
        <span className="ff-hw11-eye">How FF Party works</span>
        <h2 id="ff-phw11-h" className="ff-hw11-h">Your party bar, sorted.</h2>
        <p className="ff-hw11-t">Book professional bartenders from FF Team, the network of hospitality professionals, for your party or private event.</p>
        <ol className="ff-hw11-steps">
          {PARTY_STEPS11.map((s, i) => <li key={s.title}><span className="n">{i + 1}</span><span className="ic"><s.icon size={18} strokeWidth={1.7} /></span><b>{s.title}</b><span>{s.text}</span></li>)}
        </ol>
        <div className="ff-hw11-cta"><ShineButton onClick={nav.toEvent}><Popper11 size={15} /> Plan your event</ShineButton></div>
      </div>
    </section>
  );
}

function PartyCompanies() {
  const { state, dispatch } = useStore();
  const list = companyList(state).filter(c => !c.mine);
  return (
    <section className="ff-sect ff-pco11" id="ff-companies" aria-labelledby="ff-pco11-h">
      <h2 id="ff-pco11-h" className="ff-h1">Book a bar company</h2>
      <p className="ff-feat11-note">Book a company, then choose your bartenders from its team.</p>
      <HomeCarousel label="Bar companies">
        {list.map(co => (
          <button key={co.id} type="button" className="ff-co11-tile big" onClick={() => { dispatch({ type: "VIEW_COMPANY", id: co.id }); window.scrollTo(0, 0); }} aria-label={`${co.name}: open their page`}>
            <CompanyCardFace c={co} size="sm" />
            <span className="ff-co11-team">{(co.team || []).slice(0, 4).map(id => { const p = dirFind(id); return p ? <Portrait key={id} src={p.photo} name={p.name} size={26} tier={p.tier} /> : null; })}<small>{(co.team || []).length} on the team</small></span>
          </button>
        ))}
      </HomeCarousel>
    </section>
  );
}

/* FF Party: what we offer, and who it's for. The main content of the site, and its SEO text. */
